const anthropicOutput = $('ExtractRequirements').first().json;
const intake = $('IntakeJobDescription').first().json;
const injectionCheck = $('DetectJDPromptInjectionPatterns').first().json;

let rawText = '';
try {
  rawText = anthropicOutput.content[0].text;
} catch (e) {
  rawText = '';
}

// Same defensive parsing discipline as CANDOR-01's ParseExtractionJSON:
// the model may wrap output in markdown fences despite being told not
// to - strip that before parsing rather than assuming compliance.
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}

let extraction = null;
let parseError = null;
try {
  extraction = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

if (!extraction) {
  return [{
    json: {
      job_id: intake.job_id,
      job_title: intake.job_title,
      job_description_text: intake.job_description_text,
      prompt_injection_suspected: injectionCheck.prompt_injection_suspected,
      prompt_injection_matched_patterns: injectionCheck.prompt_injection_matched_patterns,
      extraction_status: 'PARSE_FAILED',
      parse_error: parseError,
      raw_model_output: rawText
    }
  }];
}

return [{
  json: {
    job_id: intake.job_id,
    job_title: intake.job_title,
    job_description_text: intake.job_description_text,
    prompt_injection_suspected: injectionCheck.prompt_injection_suspected,
    prompt_injection_matched_patterns: injectionCheck.prompt_injection_matched_patterns,
    extraction_status: 'PARSED_OK',
    extraction
  }
}];

const rec = $input.first().json;

if (rec.extraction_status !== 'PARSED_OK') {
  return [{ json: rec }];
}

const jdText = rec.job_description_text;
const extraction = rec.extraction;

function normalize(s) {
  return (s || '').toString().toLowerCase().replace(/\s+/g, ' ').trim();
}
const normalizedSource = normalize(jdText);

function isGrounded(quote) {
  const nq = normalize(quote);
  return nq.length > 0 && normalizedSource.includes(nq);
}

function verifyPlainField(fieldObj, fieldName) {
  if (!fieldObj || typeof fieldObj !== 'object' || !('value' in fieldObj)) {
    return { field: fieldName, value: null, source_quote: null, evidence_verified: false, reason: 'field missing or malformed in model output' };
  }
  const value = fieldObj.value;
  const quote = fieldObj.source_quote || '';
  if (typeof value === 'string' && value.trim().toLowerCase() === 'not specified') {
    return { field: fieldName, value, source_quote: quote, evidence_verified: false, reason: 'model reported not specified rather than guessing' };
  }
  if (!isGrounded(quote)) {
    return { field: fieldName, value, source_quote: quote, evidence_verified: false, reason: 'cited quote not found verbatim in source JD text (possible hallucination)' };
  }
  return { field: fieldName, value, source_quote: quote, evidence_verified: true, reason: 'quote found verbatim in source JD text' };
}

function verifyList(list, listName) {
  if (!Array.isArray(list)) return [];
  return list.map((item, i) => {
    const label = `${listName}[${i}]`;
    if (!item || typeof item !== 'object' || !('value' in item)) {
      return { field: label, value: null, source_quote: null, evidence_verified: false, reason: 'entry missing or malformed in model output' };
    }
    const value = item.value;
    const quote = item.source_quote || '';
    if (typeof value === 'string' && value.trim().toLowerCase() === 'not specified') {
      return { field: label, value, source_quote: quote, evidence_verified: false, reason: 'model reported not specified rather than guessing' };
    }
    if (!isGrounded(quote)) {
      return { field: label, value, source_quote: quote, evidence_verified: false, reason: 'cited quote not found verbatim in source JD text (possible hallucination)' };
    }
    return { field: label, value, source_quote: quote, evidence_verified: true, reason: 'quote found verbatim in source JD text' };
  });
}

// required_skills moved from a single field-level check to per-item
// verification (same discipline as other_required_qualifications /
// preferred_qualifications, and the same discipline CANDOR-01 applies to
// individual resume claims) - each skill now gets its own literal
// grounding check and its own evidence_verified status, rather than one
// shared 'this list is grounded somewhere' verdict for the whole list.
const scalarFieldNames = ['required_years_experience', 'required_certifications', 'education_requirement'];
const verifiedFields = scalarFieldNames.map(name => verifyPlainField(extraction[name], name));
const requiredSkills = verifyList(extraction.required_skills, 'required_skills');
const otherRequired = verifyList(extraction.other_required_qualifications, 'other_required_qualifications');
const preferred = verifyList(extraction.preferred_qualifications, 'preferred_qualifications');

// === v0.6 addition (System Review item 15 - OR-logic between required
// skills) === Same literal-quote grounding discipline as every other list
// here, and deliberately NOT folded into `allChecked`/`verification_summary`
// below for the same reason employment_history was kept separate on the
// candidate side (CANDOR-01-Build-Log.md v0.4 section): this JD-side
// verification_summary was never wired to any scored formula (Evidence
// Confidence reads only CANDOR-01's candidate-side summary - see
// CalculateEvidenceConfidence's own header comment), so there's no actual
// coupling risk here, but keeping the same separate-array pattern
// throughout this codebase is simpler to audit than deciding it
// case-by-case.
function verifyAlternativeSet(setObj, index) {
  const label = `required_skill_alternative_sets[${index}]`;
  if (!setObj || typeof setObj !== 'object' || !Array.isArray(setObj.options) || setObj.options.length < 2) {
    return { field: label, options: [], source_quote: null, evidence_verified: false, reason: 'entry missing, malformed, or fewer than 2 options in model output' };
  }
  const quote = setObj.source_quote || '';
  if (!isGrounded(quote)) {
    return { field: label, options: setObj.options, source_quote: quote, evidence_verified: false, reason: 'cited quote not found verbatim in source JD text (possible hallucination)' };
  }
  return { field: label, options: setObj.options, source_quote: quote, evidence_verified: true, reason: 'quote found verbatim in source JD text' };
}

const requiredSkillAlternativeSets = Array.isArray(extraction.required_skill_alternative_sets)
  ? extraction.required_skill_alternative_sets.map((s, i) => verifyAlternativeSet(s, i))
  : [];

const allChecked = [...verifiedFields, ...requiredSkills, ...otherRequired, ...preferred];
const verifiedCount = allChecked.filter(x => x.evidence_verified).length;

return [{
  json: {
    job_id: rec.job_id,
    job_title: rec.job_title,
    prompt_injection_suspected: rec.prompt_injection_suspected,
    prompt_injection_matched_patterns: rec.prompt_injection_matched_patterns,
    extraction_status: rec.extraction_status,
    processed_at: new Date().toISOString(),
    model_used: 'claude-haiku-4-5',
    fields: verifiedFields,
    required_skills: requiredSkills,
    required_skill_alternative_sets: requiredSkillAlternativeSets,
    other_required_qualifications: otherRequired,
    preferred_qualifications: preferred,
    verification_summary: {
      total_items_checked: allChecked.length,
      evidence_verified_count: verifiedCount,
      not_verified_count: allChecked.length - verifiedCount
    }
  }
}];

// === CANDOR-01 -> CANDOR-04 live wiring (2026-09-16) ===
// Same expression-with-fallback discipline as IntakeResume
// (docs/CANDOR-01-Build-Log.md, "Regression: the expression/fallback
// pattern..."): per FIELD, prefer real upstream data ($input) when
// present, fall back to the hardcoded SYN-CAND-0001 default only when
// that specific field is actually absent (`??`) - never a blanket
// "always return the hardcoded object" that silently discards real
// input regardless of what arrived. That blanket-return shape is
// exactly what broke IntakeResume's passthrough previously.
//
// This is a Code node rather than a Set node (unlike IntakeResume /
// IntakeJobDescription) because CANDOR-01's real output is one deeply
// nested record (arrays of claim objects, a nested verification_summary)
// - cramming a multi-hundred-line nested object literal into a single
// n8n Set-node expression string would itself be exactly the kind of
// brittle, hard-to-review construct CANDOR-Builder-Doctrine.md Section 5
// warns against ("solutions that relocate the failure instead of
// removing its cause"). The `??` operator here plays the identical role
// to IntakeResume's `={{ $json.field ?? "default" }}` expression: same
// operator, same per-field semantics, same failure mode guarded against
// - see scripts/candor01_to_04_passthrough_check.py, which checks this
// the same way scripts/candor02_passthrough_check.py checks IntakeResume.
//
// Default below is CANDOR-01's already-verified output on
// synthetic-resume-01.txt (execution 251, reconfirmed baseline; the
// same default IntakeCandidateRecord has used since CANDOR-04 slice 1).
// `processed_at` here is a clearly-synthetic placeholder, not a real
// captured execution timestamp - this default predates live wiring and
// was never itself produced by a real CANDOR-01 run.

const input = $input.first().json || {};

return [{
  json: {
    candidate_id: input.candidate_id ?? "SYN-CAND-0001",
    resume_filename: input.resume_filename ?? "synthetic-resume-01.txt",
    extraction_status: input.extraction_status ?? "PARSED_OK",
    resume_content_hash: input.resume_content_hash ?? "11b5f2aa56a62ecfb95144b55d9db9a5fc6d6791fa9ba752adb5f35460efe6c1",
    resume_content_hash_algorithm_version: input.resume_content_hash_algorithm_version ?? "v1.0",
    resume_shingle_fingerprint: input.resume_shingle_fingerprint ?? [],
    resume_shingle_fingerprint_version: input.resume_shingle_fingerprint_version ?? "CANDOR near-dup shingle-fingerprint v0.1",
    tenant_id: input.tenant_id ?? "default-tenant",
    processed_at: input.processed_at ?? "2026-09-16T00:00:00.000Z",
    model_used: input.model_used ?? "claude-haiku-4-5",
    fields: input.fields ?? [
      { field: "candidate_name", value: "JORDAN ELLIS RIVERA", source_quote: "JORDAN ELLIS RIVERA", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "contact_email", value: "jordan.rivera.testcandidate@example-fictional.com", source_quote: "jordan.rivera.testcandidate@example-fictional.com", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "total_years_experience_claimed", value: "7 years", source_quote: "Results-driven sales professional with 7 years of experience in B2B software sales, team leadership, and account management.", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "most_recent_title", value: "Senior Account Executive", source_quote: "Senior Account Executive — Brightline Analytics Corp (fictional company)", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "most_recent_employer", value: "Brightline Analytics Corp", source_quote: "Senior Account Executive — Brightline Analytics Corp (fictional company)", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "key_skills", value: ["Salesforce CRM", "HubSpot", "Consultative Selling", "Territory Planning", "Contract Negotiation", "Team Leadership", "Lead Scoring", "Forecasting"], source_quote: "Salesforce CRM, HubSpot, Consultative Selling, Territory Planning, Contract Negotiation, Team Leadership, Lead Scoring, Forecasting", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "education", value: "B.S. in Business Administration, Springfield State University, Graduated May 2017", source_quote: "B.S. in Business Administration, Springfield State University (fictional institution) — Graduated May 2017", evidence_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "certifications", value: "Certified Sales Professional (CSP), Fictional Sales Certification Board, issued 2019", source_quote: "Certified Sales Professional (CSP), Fictional Sales Certification Board, issued 2019", evidence_verified: true, reason: "quote found verbatim in source resume text" }
    ],
    quantified_accomplishments: input.quantified_accomplishments ?? [
      { field: "quantified_accomplishments[0]", value: "Increased regional net-new revenue by 34% over an 18-month period by restructuring the outbound prospecting workflow and introducing a tiered lead-scoring model.", evidence_verified: true },
      { field: "quantified_accomplishments[1]", value: "Closed a $420,000 annual contract with a mid-market logistics client, the largest single deal in the Southeast territory that fiscal year.", evidence_verified: true },
      { field: "quantified_accomplishments[2]", value: "Generated $1.1M in new annual recurring revenue across 60 closed deals.", evidence_verified: true },
      { field: "quantified_accomplishments[3]", value: "Reduced average sales-cycle length from 92 days to 71 days by introducing a standardized discovery-call template.", evidence_verified: true },
      { field: "quantified_accomplishments[4]", value: "Managed a book of 45 active accounts across the Southeast region.", evidence_verified: true }
    ],
    notable_unquantified_claims: input.notable_unquantified_claims ?? [
      { field: "notable_unquantified_claims[0]", value: "Recognized as a top performer and trusted advisor by leadership.", evidence_verified: false },
      { field: "notable_unquantified_claims[1]", value: "Trained and mentored 3 incoming junior account executives.", evidence_verified: true }
    ],
    // v0.4 addition (System Review item 13) - real CANDOR-01 output for
    // this same default candidate/resume (execution 892, re-confirmed
    // 2026-09-18), same "already-verified real output" discipline as every
    // other field's default in this node.
    // v0.7 update: title_verified/employer_verified added (real CANDOR-01
    // output, same execution) so this fallback default exercises
    // career_trajectory too, not just role_tenure_stability.
    employment_history: input.employment_history ?? [
      { field: "employment_history[0]", title: "Senior Account Executive", employer: "Brightline Analytics Corp (fictional company)", duration_text: "March 2021 – Present (4 years 6 months)", source_quote: "March 2021 – Present (4 years 6 months)", evidence_verified: true, title_verified: true, employer_verified: true, reason: "quote found verbatim in source resume text" },
      { field: "employment_history[1]", title: "Account Executive", employer: "Fictional Cloud Metrics Inc.", duration_text: "January 2018 – February 2021 (3 years 2 months)", source_quote: "January 2018 – February 2021 (3 years 2 months)", evidence_verified: true, title_verified: true, employer_verified: true, reason: "quote found verbatim in source resume text" }
    ],
    // v0.9 addition (System Review item 13 - portfolio/work-sample match) -
    // real CANDOR-01 output for this same default candidate (Jordan's
    // resume states no portfolio, so "insufficient information" IS the
    // real, verified value here, not a placeholder). Found and fixed a
    // real bug while verifying this factor against a real positive-case
    // fixture: this field was added to CANDOR-01's schema (v0.9) but
    // never added to THIS node's own explicit return object, so it was
    // silently dropped for every real candidate until this fix - the
    // exact "a hand-built return object must be updated by hand for every
    // new upstream field" failure mode this node's own header comment
    // already warns about, caught by real end-to-end testing, not missed.
    portfolio_or_work_sample: input.portfolio_or_work_sample ?? { field: "portfolio_or_work_sample", value: "insufficient information", source_quote: "", evidence_verified: false, reason: "model reported insufficient information rather than guessing" },
    verification_summary: input.verification_summary ?? { total_items_checked: 15, evidence_verified_count: 14, not_verified_count: 1 }
  }
}];

// === EXCLUSION ENFORCEMENT (CANDOR Master Instructions Section 7) ===
// This node is the single, structural gate between everything CANDOR-01
// extracted about a candidate (and everything extracted about the JD)
// and the scoring formula. It works as an ALLOW-LIST, not a block-list:
// it reads exactly two named properties off the candidate record and two
// off the job-requirement record, and nothing else. Every other field on
// either record - candidate_name, contact_email, most_recent_employer,
// quantified_accomplishments,
// notable_unquantified_claims, any candidate identifying detail - is
// never read, never referenced anywhere in this code, and therefore
// structurally cannot reach CalculateMatchScore, regardless of what
// CANDOR-01 (or any future intake path) happens to capture. This is
// enforced by the shape of the object literal returned below, not by a
// prompt instruction anywhere.
//
// Additions below - required_skills_detail (each skill's own
// source_quote/evidence_verified), v0.3's candidate_years_source_quote /
// required_years_source_quote, and v0.4's employment_history - do NOT
// weaken this gate in the sense that matters: every one is still read
// from an explicit, named, reviewable line below, never a blanket
// pass-through of whatever CANDOR-01 happens to produce. v0.4 (System
// Review item 13) DOES add a genuinely new candidate-side scoring input,
// on top of the original two (total_years_experience_claimed, key_skills)
// - employment_history's verified duration_text values, permitted per
// Section 7's "role tenure/stability" item. Its title/employer values are
// carried through for audit-trail readability only and are never read by
// CalculateMatchScore's scoring formula itself.
//
// Concrete example from the CANDOR-04 build spec, UPDATED for v0.8:
// candidate resume-01's `education` field value is "B.S. in Business
// Administration, Springfield State University, Graduated May 2017" -
// containing a graduation year, a documented age proxy. `education` IS
// now read (permitted input 5, v0.8), but the year itself still cannot
// reach scoring: CalculateMatchScore strips every bare 4-digit year
// token before any word-overlap comparison runs, so the literal date
// never enters the computation - gated at the point of use, not merely
// kept out at the point of read the way the rest of this allow-list
// works. `certifications` follows the identical pattern for the same
// reason (an issue year, a weaker but still real instance of the same
// class of date leakage).
//
// Input arrives from MergeCandidateAndJD (append mode: two items, one
// per upstream branch) rather than a single object, since n8n does not
// guarantee a parallel branch has executed when referenced by name
// across branches - confirmed by testing (see build log). The two items
// are told apart structurally: the JD record has a job_id field, the
// candidate record has a candidate_id field.

const items = $input.all().map(i => i.json);
const jdRecord = items.find(i => 'job_id' in i);
const candidateRecord = items.find(i => 'candidate_id' in i && 'resume_filename' in i);

// === Phase 2b (docs/CANDOR-Hardening-Roadmap-DRAFT.md) ===
// Previously, a PARSE_FAILED extraction on either side (JD or candidate)
// reached this node's `.fields.find(...)` calls with `fields` undefined,
// producing an accidental, unhelpful raw TypeError three levels deep in
// a property access - a real failure mode, but not an INTENTIONAL one.
// This turns that into a deliberate, specific, fail-loud check at the
// one place both records are first available together, instead of
// depending on where the missing `fields` array happens to blow up.
// (The candidate side is additionally already blocked further upstream -
// CANDOR-01's RouteByExtractionStatus never calls this workflow at all
// for a failed candidate extraction, System Review item 30 - this check
// is what makes CANDOR-04 safe on its own, standalone, or if that
// upstream gate is ever bypassed, not a duplicate of it.)
if (!jdRecord || jdRecord.extraction_status !== 'PARSED_OK') {
  throw new Error(`CANDOR-04 SelectPermittedScoringInputs: refusing to score - JD extraction_status is "${jdRecord ? jdRecord.extraction_status : 'missing'}", not PARSED_OK. Refusing to fall back to a stand-in or guess at required years/skills.`);
}
if (!candidateRecord || candidateRecord.extraction_status !== 'PARSED_OK') {
  throw new Error(`CANDOR-04 SelectPermittedScoringInputs: refusing to score - candidate extraction_status is "${candidateRecord ? candidateRecord.extraction_status : 'missing'}", not PARSED_OK. Refusing to fall back to a stand-in or guess at candidate years/skills.`);
}

function parseYears(text) {
  if (!text) return null;
  const m = String(text).match(/(\d+)/);
  return m ? parseInt(m[1], 10) : null;
}

// --- Permitted input 1: years of directly relevant experience (Section 7 permitted list, item 1) ---
const candidateYearsField = candidateRecord.fields.find(f => f.field === 'total_years_experience_claimed');
const candidateYears = (candidateYearsField && candidateYearsField.value !== 'insufficient information')
  ? parseYears(candidateYearsField.value)
  : null;
// The years field's own literal source_quote, carried through so
// CalculateMatchScore (v0.3) can independently judge domain relevance
// from ITS OWN evidence, rather than borrowing skill_overlap's score -
// see that node's header comment for why. Still the same permitted
// field, just its full evidentiary content instead of only its parsed
// number.
const candidateYearsSourceQuote = (candidateYearsField && candidateYearsField.value !== 'insufficient information')
  ? (candidateYearsField.source_quote || '')
  : '';

const requiredYearsField = jdRecord.fields.find(f => f.field === 'required_years_experience');
const requiredYears = (requiredYearsField && requiredYearsField.value !== 'not specified')
  ? parseYears(requiredYearsField.value)
  : null;
const requiredYearsSourceQuote = (requiredYearsField && requiredYearsField.value !== 'not specified')
  ? (requiredYearsField.source_quote || '')
  : '';

// --- Permitted input 2: explicit skill overlap with the JD (Section 7 permitted list, item 2) ---
const candidateSkillsField = candidateRecord.fields.find(f => f.field === 'key_skills');
const candidateSkills = (candidateSkillsField && Array.isArray(candidateSkillsField.value))
  ? candidateSkillsField.value.map(s => String(s).toLowerCase())
  : [];

// required_skills is now individually verified per-item (VerifyRequirementsAgainstSource) -
// each skill has its own literal source_quote and its own evidence_verified
// status, same discipline as CANDOR-01's per-claim verification, not a
// single field-level 'grounded somewhere' check. Only skills CANDOR-04 can
// independently confirm are actually required (evidence_verified === true)
// enter the scoring denominator below - an unverified 'requirement' is
// treated as unknown, exactly like the years factor above: it neither
// helps nor hurts the candidate, because we cannot confirm the JD actually
// states it.
const requiredSkillsDetail = Array.isArray(jdRecord.required_skills) ? jdRecord.required_skills : [];
const requiredSkills = requiredSkillsDetail
  .filter(item => item.evidence_verified === true)
  .map(item => String(item.value).toLowerCase());

// v0.6 (System Review item 15): only individually-verified alternative-set
// entries reach scoring, same allow-list discipline as everything else
// here - an unverified "X or Y" grouping is dropped, never guessed at,
// which means its members simply fall back to being scored as independent
// skills below (the pre-v0.6 behavior), not silently miscounted.
const requiredSkillAlternativeSets = (Array.isArray(jdRecord.required_skill_alternative_sets) ? jdRecord.required_skill_alternative_sets : [])
  .filter(s => s.evidence_verified === true)
  .map(s => ({ options: s.options.map(o => String(o).toLowerCase()), source_quote: s.source_quote }));

// --- Permitted input 3 (NEW, v0.4): role tenure/stability (Section 7 permitted list, item 4) ---
// Same allow-list discipline as the two existing inputs: only individually-
// verified entries (evidence_verified === true, i.e. CANDOR-01's own
// literal-quote grounding check against the source resume passed) reach
// scoring - an unverified or "insufficient information" entry is treated
// as unknown for that ONE role, exactly like an unverified required skill
// above, never silently dropped-but-still-counted or guessed at. `title`/
// `employer` are carried through for audit-trail readability only
// (CalculateMatchScore's own duration parser never reads them) - the only
// value that actually reaches the scoring formula is `duration_text`.
const employmentHistoryDetail = Array.isArray(candidateRecord.employment_history) ? candidateRecord.employment_history : [];
const employmentHistory = employmentHistoryDetail.filter(e => e.evidence_verified === true);

// --- Permitted input 4 (NEW, v0.7): career trajectory (Section 7 permitted list, item 5) ---
// Independent filter from role_tenure_stability's own above: only entries
// whose TITLE is independently grounded (title_verified === true, v0.7
// addition to VerifyClaimsAgainstSource) reach scoring here - regardless
// of whether that SAME entry's duration_text was also verified, since
// career trajectory needs the title regardless of whether a duration was
// ever stated (e.g. SYN-CAND-0004/Casey has two title-verified entries
// with unknown duration - usable here, excluded from tenure). employer is
// carried through for audit-trail readability only, same pattern as
// tenure's own title/employer fields - never read by CalculateMatchScore's
// trajectory logic itself.
const employmentHistoryTitles = employmentHistoryDetail.filter(e => e.title_verified === true);

// job_title is trusted intake data (a Set-node literal via IntakeJobDescription,
// not LLM-extracted) - same trust level already given to job_id, not subject
// to the literal-quote grounding discipline that governs LLM-extracted JD
// content like required_skills.
const jobTitle = jdRecord.job_title || '';

// --- Permitted input 5 (NEW, v0.8): education/certification match, ONLY
// where the JD actually requires it (Section 7 permitted list, item 6) ---
// `education` and `certifications` move from EXCLUDED to PERMITTED here -
// the header comment's own worked example (resume-01's graduation year,
// a documented age proxy) is why this pair was excluded in the first
// place. Now permitted, but ONLY as a word-overlap match against the
// JD's own stated requirement, with any bare 4-digit year token stripped
// BEFORE that comparison ever runs (CalculateMatchScore's own
// significantEducationWords()) - the literal date itself never enters
// the computation, gated at the source, not filtered out afterward.
// PERMITTED_CANDIDATE_FIELDS in BuildAuditRecord is updated to match
// (both fields removed from that node's own excluded-field leak-check
// list, since they are no longer excluded).
const educationRequirementField = jdRecord.fields.find(f => f.field === 'education_requirement');
const educationRequired = !!(educationRequirementField && educationRequirementField.value !== 'not specified' && educationRequirementField.evidence_verified === true);
const educationRequirementQuote = educationRequired ? (educationRequirementField.source_quote || '') : '';

const certificationRequirementField = jdRecord.fields.find(f => f.field === 'required_certifications');
const certificationRequired = !!(certificationRequirementField && certificationRequirementField.value !== 'not specified' && certificationRequirementField.evidence_verified === true);
const certificationRequirementQuote = certificationRequired ? (certificationRequirementField.source_quote || '') : '';

const candidateEducationField = candidateRecord.fields.find(f => f.field === 'education');
const candidateEducationVerified = !!(candidateEducationField && candidateEducationField.value !== 'insufficient information' && candidateEducationField.evidence_verified === true);
const candidateEducationText = candidateEducationVerified ? `${candidateEducationField.value} ${candidateEducationField.source_quote}` : '';

const candidateCertificationsField = candidateRecord.fields.find(f => f.field === 'certifications');
const candidateCertificationsVerified = !!(candidateCertificationsField && candidateCertificationsField.value !== 'insufficient information' && candidateCertificationsField.evidence_verified === true);
const candidateCertificationsText = candidateCertificationsVerified ? `${candidateCertificationsField.value} ${candidateCertificationsField.source_quote}` : '';

// --- Permitted input 6 (NEW, v0.9): portfolio/work-sample match, ONLY
// where PROVIDED (Section 7 permitted list, item 7 - the only factor
// gated on the CANDIDATE side rather than the JD side, unlike v0.8's
// education/certification). candidateRecord.portfolio_or_work_sample is
// a top-level field (like employment_history), not part of `fields` -
// same v0.4-established pattern for a separately-verified, denominator
// -exempt addition.
const portfolioField = candidateRecord.portfolio_or_work_sample;
const portfolioProvided = !!(portfolioField && portfolioField.value !== 'insufficient information' && portfolioField.evidence_verified === true);
const candidatePortfolioText = portfolioProvided ? `${portfolioField.value} ${portfolioField.source_quote}` : '';

// This object is the ENTIRE interface to scoring. Nothing else exists on
// it - not name, not email, not accomplishment narrative. `education`/
// `certifications` (v0.8) are the one allow-listed exception, present
// only as a requirement-gated, year-stripped word-overlap match, never
// their raw literal values.
return [{
  json: {
    candidate_id: candidateRecord.candidate_id,
    job_id: jdRecord.job_id,
    candidate_years_experience: candidateYears,
    candidate_years_source_quote: candidateYearsSourceQuote,
    required_years_experience: requiredYears,
    required_years_source_quote: requiredYearsSourceQuote,
    candidate_skills: candidateSkills,
    required_skills: requiredSkills,
    required_skills_detail: requiredSkillsDetail,
    required_skill_alternative_sets: requiredSkillAlternativeSets,
    employment_history: employmentHistory,
    employment_history_detail: employmentHistoryDetail,
    employment_history_titles: employmentHistoryTitles,
    job_title: jobTitle,
    education_required: educationRequired,
    education_requirement_quote: educationRequirementQuote,
    candidate_education_text: candidateEducationText,
    certification_required: certificationRequired,
    certification_requirement_quote: certificationRequirementQuote,
    candidate_certifications_text: candidateCertificationsText,
    portfolio_provided: portfolioProvided,
    candidate_portfolio_text: candidatePortfolioText
  }
}];

// === CANDOR-04 Deterministic Match Score — Formula Version v0.3 ===
// Code-only, no LLM invents this number (Master Instructions Section 7).
// Two permitted factors (Section 7 permitted-inputs list, items 1-2),
// each worth up to 50 points when it can be evaluated:
//   - years-of-experience sufficiency, now ALSO gated by an
//     independently-computed domain-relevance signal (new in v0.3)
//   - explicit skill overlap with the JD (unchanged since v0.2)
// Still deliberately NOT the full future formula - role tenure, career
// trajectory, education/certification match, and portfolio match remain
// unscored (see build log limitations).
//
// v0.2 -> v0.3 DESIGN PRINCIPLE, in one sentence (found via CANDOR-06's
// pool run: a candidate with 12 years in an unrelated field, zero skill
// overlap, still scored 50/100): years-of-experience credit is now
// scaled by an independently-computed domain-relevance signal derived
// from literal word-overlap between the candidate's OWN verified
// years-claim quote and the JD's OWN verified years-requirement quote -
// NEVER from the skill-overlap factor's own score - so an error in one
// factor's matching logic can never suppress a second, unrelated factor.
//
// Two alternative fixes were reviewed and rejected before this one (full
// writeup in CANDOR-04-Build-Log.md's v0.3 section):
//   - REJECTED: "zero years if skill_overlap==0" - an arbitrary cliff
//     reverse-engineered from one candidate's result, not a general
//     principle that would have been written the same way before that
//     candidate existed.
//   - REJECTED: "scale years' weight continuously by the skill_overlap
//     ratio" - couples two supposedly-independent factors together, so
//     skill_overlap's own known weakness (exact-platform-name substring
//     matching - see resume-02's discriminating case) would then
//     suppress BOTH factors instead of one.
// This fix instead gives years its own domain-relevance evidence, built
// entirely from data CANDOR-01 already extracted and already verified
// for an unrelated reason (per-field literal-quote grounding) - it
// shares no computed value with skill_overlap, so neither factor's
// weaknesses can propagate into the other.

const input = $input.first().json;
const FORMULA_VERSION = 'CANDOR-04 scoring v0.9';
// v0.8 -> v0.9 (System Review item 13, FINAL factor): added a 6TH and
// LAST permitted factor, portfolio/work-sample match (Section 7
// permitted-inputs list, item 7 - the final one). Gated on the CANDIDATE
// side ("where provided"), unlike v0.8's JD-side gating - most resumes
// legitimately have no portfolio, especially for a sales role, and this
// factor correctly excludes itself rather than scoring a 0 when that's
// true (confirmed against all 6 real pool candidates: none provide one).
// Domain-gated via the SAME reused yearsDomainRelevance() signal as
// tenure/trajectory (4th reuse) - a provided-but-irrelevant portfolio
// (e.g. a photography portfolio for a sales role) should not earn full
// credit any more than irrelevant years or tenure should. Verified
// against a real, purpose-built positive-case fixture
// (samples/synthetic-resume-13-portfolio-test.txt) since none of the 6
// real pool candidates provide one - see CANDOR-04-Build-Log.md.
// v0.7 -> v0.8 (System Review item 13, continued): added a 5TH permitted
// factor, education/certification match (Section 7 permitted-inputs list,
// item 6) - the ONLY factor in this formula that is gated at the SOURCE,
// per Section 7's own explicit qualifier "where the job actually requires
// it": if the JD's own education_requirement/required_certifications
// fields both come back "not specified" (checked independently), this
// factor is not evaluated at all, not scored as a 0. On this project's
// real, current JD, BOTH mentions ("Bachelor's degree...",
// "Relevant sales certification...") sit under PREFERRED QUALIFICATIONS,
// never REQUIRED - confirmed by inspecting the real extraction output
// before writing any scoring code, not assumed - so this factor correctly
// excludes itself for every real candidate against today's real JD. See
// CANDOR-04-Build-Log.md for a real positive match verified against a
// deliberately-overridden test JD that DOES require one. Weighted
// identically to the other 4 (50 points each when evaluated).
// v0.6 -> v0.7 (System Review item 13, continued): added a 4TH permitted
// factor, career trajectory (Section 7 permitted-inputs list, item 5),
// built on v0.7's own new CANDOR-01 addition - title/employer are now
// independently literal-quote-grounded (title_verified/employer_verified),
// decoupled from whether that same role's duration_text verified (career
// trajectory needs the title regardless of whether a duration was ever
// stated). Weighted identically to the other 3 (50 points each when
// evaluated) - same equal-weight-of-whatever-evaluates normalization
// already established since v0.1, no formula change needed to support a
// 4th factor. Domain-gated the SAME way years/tenure already are (reusing
// yearsDomainRelevance() a third time, still never touching skill_overlap's
// own weaker matching) - see the factor's own block below for why this
// was non-negotiable, not an afterthought.
// v0.5 -> v0.6 (System Review item 15): a JD's "Salesforce or HubSpot" is
// now scored as ONE either/or requirement slot, satisfied by matching
// ANY option in it, instead of two independent partial-credit items (a
// candidate who names only one of the two acceptable platforms used to
// score 1/2 on this requirement; the JD only ever asked for one of them,
// so that candidate has now fully satisfied it - 1/1). See the
// alternative-set slot-counting logic inside the skill_overlap block
// below for the mechanism; composes with v0.5's synonym map rather than
// replacing it (skillsEquivalent() is reused unchanged for matching each
// option).
// v0.4 -> v0.5 (System Review item 14): skill_overlap's matching gained a
// curated synonym/abbreviation map, closing the specific gap named in the
// review ("Salesforce" matches "Salesforce CRM" but not "SFDC") without
// open-ended embedding similarity (that alternative was explicitly ruled
// out by this item's own scope, not just unconsidered). See
// skillsEquivalent() below for the map itself and the false-positive-risk
// reasoning behind each entry (and each deliberately-omitted entry).
// v0.3 -> v0.4 (System Review item 13): added a THIRD permitted factor,
// role tenure/stability (Section 7 permitted-inputs list, item 4), scored
// from CANDOR-01's new (additive-only) `employment_history` extraction.
// Weighted identically to the other two (50 points each when evaluated) -
// the existing weightedSum/totalWeight normalization below already
// generalizes to any number of factors without changes: whatever subset
// evaluates is equal-weight-averaged. Absent this project's own outcome
// data to calibrate relative weights (Section 7: "weightings may be
// calibrated later"), equal weighting is the least-arbitrary default -
// the same choice already made implicitly for years/skills since v0.1.
//
// DOMAIN-GATED, same as years-of-experience (v0.3), for the SAME reason
// v0.3 exists: an early version of this fix (tested against this exact
// pool before being finalized, not assumed safe) scored a stable-but-
// completely-unrelated-field candidate (a 12-year construction PM, zero
// sales-domain overlap) at full tenure credit on raw duration alone -
// reproducing, via a brand-new factor, the exact "irrelevant experience
// inflates the score" bug v0.3 was built to fix for years. Reusing the
// SAME domain-relevance signal already computed for years (never
// skill_overlap's - same non-coupling principle v0.3 already established)
// closes that gap without a second, separately-fallible domain check.
// Only 3 other scored factors exist in this project total, and item 14
// (skill-matching precision) is a separate, not-yet-built fix - reusing
// years' domain signal here, rather than skill_overlap's, keeps this
// factor unaffected by that still-open weakness.

const factorsUsed = [];
let weightedSum = 0;
let totalWeight = 0;

// --- Shared helper: literal, deterministic word-overlap check ---
// Same spirit as VerifyClaimsAgainstSource's isGrounded() - simple,
// transparent, stated explicitly rather than hidden inside a black-box
// similarity library. Stopwords deliberately include the generic
// years/experience scaffolding words every "N years of experience..."
// sentence shares, so overlap only counts actual DOMAIN vocabulary
// (e.g. "B2B", "software", "sales"), not sentence structure.
const YEARS_DOMAIN_STOPWORDS = new Set([
  'a','an','the','of','in','on','with','and','or','to','for','by','at','is','as',
  'that','this','these','those','from','into','across','over','under',
  'years','year','experience','experienced','plus','more','professional'
]);

function significantWords(text) {
  return new Set(
    String(text || '')
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(w => w.length > 2 && !YEARS_DOMAIN_STOPWORDS.has(w))
  );
}

// Returns { score: 0|1, shared_words, jd_words_checked, reason }.
// score is 1 (full credit, i.e. "not disqualified on relevance grounds")
// when EITHER (a) the JD's own years-requirement quote has no checkable
// domain vocabulary at all - nothing to compare against, so this signal
// abstains rather than guessing a penalty - OR (b) at least one
// significant domain word is shared between the two quotes. score is 0
// only when the JD DOES state checkable domain vocabulary and NONE of it
// appears anywhere in the candidate's own years-context quote - a real,
// positive absence of relevance, not a guess.
//
// This is a BINARY signal (like every other literal-grounding check in
// this codebase, e.g. isGrounded()), not a continuous "what fraction of
// the JD's exact words matched" ratio - a continuous ratio was tried
// against this pool first and rejected: it penalized resume-01 (7 years,
// "B2B software sales") for not also repeating the JD's exact synonym
// "SaaS", even though "B2B software sales" is obviously the same domain
// - the same class of brittle-exact-matching fragility this fix exists
// to avoid reproducing (see CANDOR-04-Build-Log.md for the worked
// example). Requiring only ONE shared domain word for full credit avoids
// that fragility while still correctly producing 0 when there is
// genuinely zero domain overlap (e.g. a construction-management resume
// against a B2B software sales requirement).
function yearsDomainRelevance(candidateYearsQuote, requiredYearsQuote) {
  const jdWords = significantWords(requiredYearsQuote);
  if (jdWords.size === 0) {
    return { score: 1, shared_words: [], jd_words_checked: [], reason: "JD years-requirement quote has no checkable domain vocabulary - signal abstains rather than penalizing" };
  }
  const candidateWords = significantWords(candidateYearsQuote);
  const shared = [...jdWords].filter(w => candidateWords.has(w));
  return {
    score: shared.length > 0 ? 1 : 0,
    shared_words: shared,
    jd_words_checked: [...jdWords],
    reason: shared.length > 0
      ? `candidate's years-context quote shares domain vocabulary with the JD's years-requirement quote: ${shared.join(', ')}`
      : `candidate's years-context quote shares NO domain vocabulary with the JD's years-requirement quote (checked against: ${[...jdWords].join(', ')})`
  };
}

// A skipped factor is excluded from the denominator entirely, not scored
// as 0 against a fixed maximum - totalWeight only grows when a factor
// actually runs (unchanged principle since v0.2).
let yearsComponent = null;
let yearsSufficiencyComponent = null;
let yearsDomainRelevanceResult = null;
if (input.required_years_experience !== null && input.candidate_years_experience !== null) {
  yearsSufficiencyComponent = input.candidate_years_experience >= input.required_years_experience
    ? 1
    : Math.max(0, input.candidate_years_experience / input.required_years_experience);
  yearsDomainRelevanceResult = yearsDomainRelevance(input.candidate_years_source_quote, input.required_years_source_quote);
  yearsComponent = yearsSufficiencyComponent * yearsDomainRelevanceResult.score;
  weightedSum += 50 * yearsComponent;
  totalWeight += 50;
  factorsUsed.push('years_of_experience');
}

// --- Permitted input 3 (NEW in v0.4): role tenure/stability (Section 7 permitted list, item 4) ---
// Deterministic duration parsing - the LLM only ever extracted a literal
// date-range/duration phrase (CANDOR-01-Build-Log.md), never computed a
// number itself (Section 7: "the final score must be calculated
// deterministically by code"). Checked, in priority order, against every
// duration format actually observed in this project's real fixtures (not
// a speculative general-purpose date parser): an author-stated
// parenthetical (most precise, e.g. "(4 years 6 months)"), a bare
// duration with no dates at all (e.g. "3 years"), a "YYYY - Present"
// range, and a "YYYY - YYYY" range. Anything none of these match returns
// null - unparseable is excluded from scoring, never guessed at.
function parseDurationYears(durationText) {
  if (!durationText || typeof durationText !== 'string') return null;
  const text = durationText.trim();
  const paren = text.match(/\((\d+)\s*years?(?:[,\s]+(\d+)\s*months?)?\)/i);
  if (paren) {
    const yrs = parseInt(paren[1], 10);
    const mos = paren[2] ? parseInt(paren[2], 10) : 0;
    return yrs + mos / 12;
  }
  const bare = text.match(/^(\d+(?:\.\d+)?)\s*(?:years?|yrs?)\s*$/i);
  if (bare) return parseFloat(bare[1]);
  const CURRENT_YEAR = new Date().getFullYear();
  const toPresent = text.match(/((?:19|20)\d{2}).{0,5}?(present|current|now)/i);
  if (toPresent) return Math.max(0, CURRENT_YEAR - parseInt(toPresent[1], 10));
  const range = text.match(/((?:19|20)\d{2}).{0,5}?((?:19|20)\d{2})/);
  if (range) return Math.max(0, parseInt(range[2], 10) - parseInt(range[1], 10));
  return null;
}

const STABLE_TENURE_YEARS_THRESHOLD = 2; // a widely-used general recruiting
  // benchmark for "not a tenure red flag," not derived from this project's
  // own outcome data (none exists yet) - same category of reasoned-but-
  // provisional constant as BuildFinalRecord's HIGH_THRESHOLD, explicitly
  // named and versioned so it's revisitable later, not hidden inline.

let tenureComponent = null;
let averageTenureYears = null;
let tenureSufficiencyComponent = null;
let tenureDomainRelevanceResult = null;
const tenureEntriesConsidered = (Array.isArray(input.employment_history) ? input.employment_history : [])
  .map(e => ({ title: e.title, employer: e.employer, duration_text: e.duration_text, parsed_years: parseDurationYears(e.duration_text) }))
  .filter(e => e.parsed_years !== null);

if (tenureEntriesConsidered.length > 0) {
  averageTenureYears = tenureEntriesConsidered.reduce((sum, e) => sum + e.parsed_years, 0) / tenureEntriesConsidered.length;
  tenureSufficiencyComponent = averageTenureYears >= STABLE_TENURE_YEARS_THRESHOLD
    ? 1
    : Math.max(0, averageTenureYears / STABLE_TENURE_YEARS_THRESHOLD);

  // Reuse years' own domain-relevance signal (see header comment). When no
  // years-summary quote exists at all (years factor itself excluded as
  // unknown), there is no domain evidence to check tenure against either
  // way - abstain (full credit) rather than penalize, consistent with
  // this project's "unknown is not a penalty" principle throughout.
  tenureDomainRelevanceResult = input.candidate_years_source_quote
    ? yearsDomainRelevance(input.candidate_years_source_quote, input.required_years_source_quote)
    : { score: 1, shared_words: [], jd_words_checked: [], reason: "no candidate years-summary quote available to check domain relevance against - signal abstains rather than penalizing an already-separate factor" };

  tenureComponent = tenureSufficiencyComponent * tenureDomainRelevanceResult.score;
  weightedSum += 50 * tenureComponent;
  totalWeight += 50;
  factorsUsed.push('role_tenure_stability');
}

// --- Permitted input 4 (NEW in v0.7): career trajectory (Section 7 permitted list, item 5) ---
// Curated, bounded title-seniority ranking - same discipline as v0.5's
// skill synonym map: a small, individually-reviewed lookup, not an
// open-ended NLP/embedding classifier. Checked in a DELIBERATE priority
// order, not numeric rank order: a specific qualifier prefix
// ("junior"/"associate"/"senior") is checked BEFORE a generic role noun
// ("manager"), because a role noun like "manager" appears inside titles
// at every real seniority level in this project's own fixtures ("Account
// Manager" is an individual-contributor sales title, not literally a
// people-manager) - checking rank-order-first would let that generic
// noun outrank a real, deliberate qualifier sitting right next to it in
// the same title (found and corrected during this factor's own design,
// not assumed correct on the first pass - see CANDOR-04-Build-Log.md).
const SENIORITY_TIERS = [
  { rank: 1, keywords: ['junior', 'jr.', 'jr ', 'associate', 'assistant', 'intern', 'entry-level', 'entry level', 'coordinator'] },
  { rank: 3, keywords: ['senior', 'sr.', 'sr '] },
  { rank: 7, keywords: ['chief executive', 'chief financial', 'chief operating', 'chief technology', 'chief ', ' ceo', ' cfo', ' coo', ' cto'] },
  { rank: 6, keywords: ['vice president', 'vp '] },
  { rank: 5, keywords: ['director'] },
  { rank: 4, keywords: ['manager', 'head of', 'lead ', 'principal'] },
];
const BASELINE_SENIORITY_RANK = 2; // no qualifier/role-noun matched - an individual-contributor default, not "unknown"

function seniorityRank(title) {
  const t = ` ${String(title || '').toLowerCase()} `;
  for (const tier of SENIORITY_TIERS) {
    if (tier.keywords.some(kw => t.includes(kw))) return tier.rank;
  }
  return BASELINE_SENIORITY_RANK;
}

let trajectoryComponent = null;
let trajectoryProgressionComponent = null;
let trajectorySufficiencyComponent = null;
let trajectoryDomainRelevanceResult = null;
let mostRecentTitleRank = null;
let requiredTitleRank = null;
const titleEntriesConsidered = (Array.isArray(input.employment_history_titles) ? input.employment_history_titles : [])
  .map(e => ({ title: e.title, rank: seniorityRank(e.title) }));

if (titleEntriesConsidered.length > 0) {
  // Entries arrive in the order CANDOR-01 extracted them - "the order the
  // resume lists them" per its own schema instruction, i.e. most recent
  // first for a normally-formatted reverse-chronological resume (the only
  // format this project's real fixtures use - stated as a real, named
  // assumption, not hidden).
  mostRecentTitleRank = titleEntriesConsidered[0].rank;
  requiredTitleRank = seniorityRank(input.job_title);

  trajectorySufficiencyComponent = mostRecentTitleRank >= requiredTitleRank
    ? 1
    : Math.max(0, mostRecentTitleRank / requiredTitleRank);

  // Progression only computable with >=2 real title entries - a single
  // role has a current level but no observable TREND, and asserting one
  // from one data point would be a guess, not a measurement. Skipped from
  // the average entirely when not computable (not defaulted to a value),
  // same "unknown is not a penalty AND not a free pass" principle already
  // applied to years/tenure's own abstain cases.
  if (titleEntriesConsidered.length > 1) {
    const earliestRank = titleEntriesConsidered[titleEntriesConsidered.length - 1].rank;
    trajectoryProgressionComponent = mostRecentTitleRank >= earliestRank ? 1 : 0;
  }

  // Reuse years' own domain-relevance signal (see role_tenure_stability's
  // header comment for the full reasoning - same non-coupling principle,
  // third reuse of the same pure function). Without this gate, an early
  // version of this factor (tested against this pool before being
  // finalized) scored SYN-CAND-0006 (12yr construction PM, zero sales
  // -domain overlap) at full trajectory credit purely from title-noun
  // matching ("Project Manager" outranks the JD's own "Manager" bar) -
  // reproducing, via a THIRD new factor, the exact bug v0.3 exists to
  // prevent. Same abstain-on-no-quote handling as tenure's own reuse.
  trajectoryDomainRelevanceResult = input.candidate_years_source_quote
    ? yearsDomainRelevance(input.candidate_years_source_quote, input.required_years_source_quote)
    : { score: 1, shared_words: [], jd_words_checked: [], reason: "no candidate years-summary quote available to check domain relevance against - signal abstains rather than penalizing an already-separate factor" };

  const subComponents = [trajectorySufficiencyComponent];
  if (trajectoryProgressionComponent !== null) subComponents.push(trajectoryProgressionComponent);
  const rawTrajectoryScore = subComponents.reduce((a, b) => a + b, 0) / subComponents.length;

  trajectoryComponent = rawTrajectoryScore * trajectoryDomainRelevanceResult.score;
  weightedSum += 50 * trajectoryComponent;
  totalWeight += 50;
  factorsUsed.push('career_trajectory');
}

// --- Permitted input 5 (NEW in v0.8): education/certification match, ONLY
// where the JD actually requires it (Section 7 permitted list, item 6) ---
// AGE-PROXY HANDLING (Section 7's own named concern - education commonly
// states a graduation year): every bare 4-digit year token is stripped
// from BOTH sides' text BEFORE any word-overlap comparison runs - a year
// can never enter the match computation, not filtered out afterward. This
// is otherwise the SAME literal-word-overlap discipline as
// yearsDomainRelevance() above (binary signal, curated stopwords, abstain
// when the requirement quote has no checkable vocabulary) - deliberately
// reused in spirit, not a fourth independently-invented matching style.
const EDUCATION_STOPWORDS = new Set([
  'a','an','the','of','in','on','with','and','or','to','for','by','at','is','as',
  'that','this','these','those','from','into','across','over','under',
  'degree','degrees','field','related','relevant','equivalent'
]);

function stripYears(text) {
  return String(text || '').replace(/\b(19|20)\d{2}\b/g, ' ');
}

function significantEducationWords(text) {
  return new Set(
    stripYears(text)
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(w => w.length > 2 && !EDUCATION_STOPWORDS.has(w))
  );
}

function requirementOverlap(candidateText, requirementQuote) {
  const reqWords = significantEducationWords(requirementQuote);
  if (reqWords.size === 0) {
    return { score: 1, shared_words: [], jd_words_checked: [], reason: "requirement quote has no checkable vocabulary - signal abstains rather than penalizing" };
  }
  const candWords = significantEducationWords(candidateText);
  const shared = [...reqWords].filter(w => candWords.has(w));
  return {
    score: shared.length > 0 ? 1 : 0,
    shared_words: shared,
    jd_words_checked: [...reqWords],
    reason: shared.length > 0
      ? `candidate's text shares vocabulary with the JD's requirement: ${shared.join(', ')}`
      : `candidate's text shares NO vocabulary with the JD's requirement (checked against: ${[...reqWords].join(', ')})`
  };
}

let educationComponent = null;
let certificationComponent = null;
let educationEvidence = null;
let certificationEvidence = null;

if (input.education_required) {
  educationEvidence = requirementOverlap(input.candidate_education_text, input.education_requirement_quote);
  educationComponent = educationEvidence.score;
}
if (input.certification_required) {
  certificationEvidence = requirementOverlap(input.candidate_certifications_text, input.certification_requirement_quote);
  certificationComponent = certificationEvidence.score;
}

let educationCertComponent = null;
if (educationComponent !== null || certificationComponent !== null) {
  const subs = [];
  if (educationComponent !== null) subs.push(educationComponent);
  if (certificationComponent !== null) subs.push(certificationComponent);
  educationCertComponent = subs.reduce((a, b) => a + b, 0) / subs.length;
  weightedSum += 50 * educationCertComponent;
  totalWeight += 50;
  factorsUsed.push('education_certification_match');
}

// --- Permitted input 6 (NEW in v0.9, FINAL factor): portfolio/work-sample
// match, ONLY where PROVIDED (Section 7 permitted list, item 7) ---
let portfolioComponent = null;
let portfolioDomainRelevanceResult = null;
if (input.portfolio_provided) {
  // Reuse years' own domain-relevance signal (see role_tenure_stability's
  // header comment for the full reasoning - same non-coupling principle,
  // 4th reuse of the same pure function). A provided-but-domain-irrelevant
  // portfolio (e.g. a photography portfolio submitted for a sales role)
  // should not earn full credit any more than irrelevant years or tenure
  // should - same abstain-on-no-quote handling as every prior reuse.
  portfolioDomainRelevanceResult = input.candidate_years_source_quote
    ? yearsDomainRelevance(input.candidate_years_source_quote, input.required_years_source_quote)
    : { score: 1, shared_words: [], jd_words_checked: [], reason: "no candidate years-summary quote available to check domain relevance against - signal abstains rather than penalizing an already-separate factor" };
  portfolioComponent = portfolioDomainRelevanceResult.score;
  weightedSum += 50 * portfolioComponent;
  totalWeight += 50;
  factorsUsed.push('portfolio_work_sample_match');
}

// Curated synonym/abbreviation map - deliberately narrow, each entry
// individually reviewed for false-positive risk rather than padded to
// look thorough. "sfdc" is an unambiguous, widely-recognized industry-
// standard abbreviation for Salesforce.com - safe to treat as
// equivalent. No HubSpot entry exists: no comparably unambiguous,
// widely-recognized short form was found (a candidate like "HS" would
// collide with too many unrelated things a resume could mean) -
// inventing one for symmetry's own sake would be exactly the kind of
// unreviewed guess this item's instruction warns against, not a genuine
// improvement. Scoped to what this project's real JD/skill vocabulary
// actually needs today, not speculatively broadened to tools that
// have never appeared in a real run here.
const SKILL_SYNONYMS = {
  'salesforce': ['sfdc']
};

function skillsEquivalent(candidateSkill, requiredSkill) {
  if (candidateSkill.includes(requiredSkill) || requiredSkill.includes(candidateSkill)) return true;
  for (const canonical in SKILL_SYNONYMS) {
    const group = [canonical, ...SKILL_SYNONYMS[canonical]];
    const candidateInGroup = group.some(g => candidateSkill.includes(g));
    const requiredInGroup = group.some(g => requiredSkill.includes(g));
    if (candidateInGroup && requiredInGroup) return true;
  }
  return false;
}

// Alternative-set-aware slot counting (v0.6): every required skill that
// belongs to a verified "X or Y" group counts toward ONE shared slot for
// that group (satisfied if ANY option matches), not one slot per skill
// name. A required skill NOT named in any alternative set is still its
// own independent slot, unchanged from v0.5.
const alternativeSets = Array.isArray(input.required_skill_alternative_sets) ? input.required_skill_alternative_sets : [];
const skillsInAlternativeSets = new Set();
alternativeSets.forEach(set => (set.options || []).forEach(opt => skillsInAlternativeSets.add(opt)));

const independentRequiredSkills = input.required_skills.filter(req => !skillsInAlternativeSets.has(req));

let skillsComponent = null;
let matchedSkills = [];
let alternativeSetResults = [];
const totalSlots = independentRequiredSkills.length + alternativeSets.length;
if (totalSlots > 0) {
  const matchedIndependentSkills = independentRequiredSkills.filter(req =>
    input.candidate_skills.some(cs => skillsEquivalent(cs, req))
  );
  alternativeSetResults = alternativeSets.map(set => {
    const options = set.options || [];
    // Report EVERY option the candidate actually has evidence for, not
    // just the first one a naive .find() would hit - satisfied/scoring
    // only needs one match, but the audit trail (and downstream pool
    // -wide per-skill reporting, e.g. candor06_pool_bias_audit.py) needs
    // the complete, honest picture: a candidate who genuinely lists BOTH
    // Salesforce and HubSpot should show both as matched, not silently
    // have one hidden because the slot was already satisfied by the
    // other. Found as a real accuracy gap while refreshing CANDOR-06's
    // pool under this same formula version (CANDOR-06-Build-Log.md) -
    // matched_option (singular) kept for backward compatibility,
    // matched_options (plural) is the complete list.
    const matchedOptions = options.filter(opt => input.candidate_skills.some(cs => skillsEquivalent(cs, opt)));
    return { options, source_quote: set.source_quote, satisfied: matchedOptions.length > 0, matched_option: matchedOptions[0] || null, matched_options: matchedOptions };
  });
  const satisfiedSlots = matchedIndependentSkills.length + alternativeSetResults.filter(r => r.satisfied).length;
  matchedSkills = [...matchedIndependentSkills, ...alternativeSetResults.flatMap(r => r.matched_options)];
  skillsComponent = satisfiedSlots / totalSlots;
  weightedSum += 50 * skillsComponent;
  totalWeight += 50;
  factorsUsed.push('skill_overlap');
}

const matchScore = totalWeight > 0 ? Math.round((weightedSum / totalWeight) * 100) : null;

return [{
  json: {
    candidate_id: input.candidate_id,
    job_id: input.job_id,
    match_score: matchScore,
    match_score_formula_version: FORMULA_VERSION,
    factors_used: factorsUsed,
    factor_detail: {
      years_of_experience: {
        candidate_years: input.candidate_years_experience,
        required_years: input.required_years_experience,
        sufficiency_component_0_to_1: yearsSufficiencyComponent,
        domain_relevance_component_0_to_1: yearsDomainRelevanceResult ? yearsDomainRelevanceResult.score : null,
        domain_relevance_evidence: yearsDomainRelevanceResult ? {
          candidate_years_source_quote: input.candidate_years_source_quote,
          required_years_source_quote: input.required_years_source_quote,
          shared_domain_words: yearsDomainRelevanceResult.shared_words,
          jd_domain_words_checked: yearsDomainRelevanceResult.jd_words_checked,
          reason: yearsDomainRelevanceResult.reason
        } : null,
        component_score_0_to_1: yearsComponent
      },
      skill_overlap: {
        required_skills: input.required_skills,
        required_skills_detail: input.required_skills_detail,
        independent_required_skills: independentRequiredSkills,
        alternative_sets: alternativeSetResults,
        candidate_skills: input.candidate_skills,
        matched_skills: matchedSkills,
        required_count: totalSlots,
        component_score_0_to_1: skillsComponent
      },
      role_tenure_stability: {
        entries_considered: tenureEntriesConsidered,
        average_tenure_years: averageTenureYears,
        stability_threshold_years: STABLE_TENURE_YEARS_THRESHOLD,
        sufficiency_component_0_to_1: tenureSufficiencyComponent,
        domain_relevance_component_0_to_1: tenureDomainRelevanceResult ? tenureDomainRelevanceResult.score : null,
        domain_relevance_evidence: tenureDomainRelevanceResult,
        component_score_0_to_1: tenureComponent
      },
      career_trajectory: {
        title_entries_considered: titleEntriesConsidered,
        most_recent_title_rank: mostRecentTitleRank,
        required_title_rank: requiredTitleRank,
        required_job_title: input.job_title,
        sufficiency_component_0_to_1: trajectorySufficiencyComponent,
        progression_component_0_to_1: trajectoryProgressionComponent,
        domain_relevance_component_0_to_1: trajectoryDomainRelevanceResult ? trajectoryDomainRelevanceResult.score : null,
        domain_relevance_evidence: trajectoryDomainRelevanceResult,
        component_score_0_to_1: trajectoryComponent
      },
      education_certification_match: {
        education_required: input.education_required,
        education_requirement_quote: input.education_requirement_quote,
        education_evidence: educationEvidence,
        education_component_0_to_1: educationComponent,
        certification_required: input.certification_required,
        certification_requirement_quote: input.certification_requirement_quote,
        certification_evidence: certificationEvidence,
        certification_component_0_to_1: certificationComponent,
        component_score_0_to_1: educationCertComponent
      },
      portfolio_work_sample_match: {
        portfolio_provided: input.portfolio_provided,
        domain_relevance_component_0_to_1: portfolioDomainRelevanceResult ? portfolioDomainRelevanceResult.score : null,
        domain_relevance_evidence: portfolioDomainRelevanceResult,
        component_score_0_to_1: portfolioComponent
      }
    }
  }
}];

// === CANDOR-04 Evidence Confidence — Formula Version v0.1 ===
// Deliberately independent of CalculateMatchScore (Master Instructions
// Section 6): this node reads ONLY the candidate's CANDOR-01
// verification_summary (how many extracted claims survived literal,
// deterministic verification against the source resume). It never reads
// match_score, years, skills, or anything from the JD side - it is not
// even connected to that branch of the workflow. A change to the scoring
// formula's weights can never move this number, and vice versa.
// v0.1 limitation: single-factor proxy (fraction of claims verified).
// Does not yet incorporate every factor listed in Section 24 (internal
// date consistency, contradiction detection) - future work, exactly as
// the Match Score formula is also a v0.1 slice.

const candidateRecord = $input.first().json;
const summary = candidateRecord.verification_summary || {};

const total = summary.total_items_checked || 0;
const verified = summary.evidence_verified_count || 0;
const evidenceConfidence = total > 0 ? Math.round((verified / total) * 100) : null;

return [{
  json: {
    candidate_id: candidateRecord.candidate_id,
    evidence_confidence: evidenceConfidence,
    evidence_confidence_formula_version: 'CANDOR-04 evidence-confidence v0.1',
    basis: {
      total_items_checked: total,
      evidence_verified_count: verified
    }
  }
}];

// Combines the two independently-computed numbers into one report - never
// blended into a single score. This is the ONLY node that sees both.
// Neither CalculateMatchScore nor CalculateEvidenceConfidence reads the
// other's output; this node reads both purely for final display, after
// MergeScoreAndConfidence (append mode) guarantees both have executed.

const items = $input.all().map(i => i.json);
const matchItem = items.find(i => 'match_score' in i);
const evidenceItem = items.find(i => 'evidence_confidence' in i);

// The single cutoff that separates "high" from "low" for BOTH match_score
// and evidence_confidence in the 2x2 interpretation matrix below - the
// exact code a 50 and a 55 both fell under ("RELIABLY NOT A FIT") during
// CANDOR-06's pool run, since both are < 60. Versioned explicitly (was an
// unversioned inline constant before CANDOR-06's review) so a future
// change to this cutoff is traceable the same way the scoring formulas
// already are.
const INTERPRETATION_THRESHOLD_VERSION = 'CANDOR-04 interpretation-threshold v0.1';
const HIGH_THRESHOLD = 60; // same convention as UOR-01's own threshold

function interpret(matchScore, evidenceConfidence) {
  if (matchScore === null || evidenceConfidence === null) {
    return 'INSUFFICIENT DATA FOR INTERPRETATION';
  }
  const highMatch = matchScore >= HIGH_THRESHOLD;
  const highEvidence = evidenceConfidence >= HIGH_THRESHOLD;
  if (highMatch && highEvidence) return 'STRONG CANDIDATE FOR RECRUITER REVIEW';
  if (highMatch && !highEvidence) return 'PROMISING - VERIFY BEFORE PRIORITIZING';
  if (!highMatch && highEvidence) return 'RELIABLY NOT A FIT FOR THIS ROLE';
  return 'INSUFFICIENT INFORMATION';
}

return [{
  json: {
    candidate_id: matchItem.candidate_id,
    job_id: matchItem.job_id,
    match_score: matchItem.match_score,
    match_score_formula_version: matchItem.match_score_formula_version,
    match_score_factors_used: matchItem.factors_used,
    match_score_factor_detail: matchItem.factor_detail,
    evidence_confidence: evidenceItem.evidence_confidence,
    evidence_confidence_formula_version: evidenceItem.evidence_confidence_formula_version,
    evidence_confidence_basis: evidenceItem.basis,
    interpretation: interpret(matchItem.match_score, evidenceItem.evidence_confidence),
    interpretation_threshold_version: INTERPRETATION_THRESHOLD_VERSION,
    interpretation_threshold: HIGH_THRESHOLD,
    interpretation_note: 'Decision support only, per CANDOR Master Instructions Section 26 - does not authorize rejecting, advancing, or contacting this candidate. No combination of these scores overrides human review.',
    scored_at: new Date().toISOString()
  }
}];

// === CANDOR-05 Bias & Fairness Audit Layer - Slice 1: per-run audit record ===
// CANDOR Master Instructions Section 8. This node adds NO new scoring
// logic and changes NOTHING about how Match Score or Evidence Confidence
// are calculated - it only assembles a self-contained, human-readable
// audit record from CANDOR-04's existing output, so a reviewer doesn't
// have to hunt across nodes.
//
// Per Section 8 exactly, this record contains FOUR things:
//   (a) which inputs were actually used to calculate the Match Score
//   (b) confirmation - derived programmatically, not just asserted - that
//       no excluded/protected-characteristic field reached the formula
//   (c) the raw extracted claims/quotes behind each scoring factor
//   (d) a flag for when Evidence Confidence is too low to treat the
//       Match Score as reliable
//
// This is a DIAGNOSTIC AID for the human reviewer who remains responsible
// for the hiring process. It is NOT, and must never be treated as, a
// certification of legal or bias compliance (Section 8). See
// `audit_disclaimer` below - the same language appears in the build log
// and the sticky note, deliberately, so it can't be missed in any one
// place.

const finalRecord = $input.first().json;
const candidateRecord = $('IntakeCandidateRecord').first().json;

const AUDIT_SCHEMA_VERSION = 'CANDOR-05 audit-record v0.1';
const FLAG_VERSION = 'CANDOR-05 audit-flag v0.1';
const EVIDENCE_CONFIDENCE_FLAG_THRESHOLD = 50;

const detail = finalRecord.match_score_factor_detail || {};
const factorsUsed = finalRecord.match_score_factors_used || [];

// --- (a) Which inputs were actually used ---
const yearsUsed = factorsUsed.includes('years_of_experience');
const skillsUsed = factorsUsed.includes('skill_overlap');
const tenureUsed = factorsUsed.includes('role_tenure_stability');
const trajectoryUsed = factorsUsed.includes('career_trajectory');
const educationCertUsed = factorsUsed.includes('education_certification_match');
const portfolioUsed = factorsUsed.includes('portfolio_work_sample_match');

const skillDetail = detail.skill_overlap || {};
const requiredSkillsDetail = Array.isArray(skillDetail.required_skills_detail) ? skillDetail.required_skills_detail : [];
const requiredSkillsCounted = requiredSkillsDetail.filter(s => s.evidence_verified === true);
const requiredSkillsExcludedUnverified = requiredSkillsDetail.filter(s => s.evidence_verified !== true);

const yearsDetail = detail.years_of_experience || {};
const tenureDetail = detail.role_tenure_stability || {};
const trajectoryDetail = detail.career_trajectory || {};
const educationCertDetail = detail.education_certification_match || {};
const portfolioDetail = detail.portfolio_work_sample_match || {};

const matchScoreInputsUsed = {
  factors_used: factorsUsed,
  years_of_experience: yearsUsed ? {
    candidate_years: yearsDetail.candidate_years,
    required_years: yearsDetail.required_years,
    sufficiency_component_0_to_1: yearsDetail.sufficiency_component_0_to_1,
    domain_relevance_component_0_to_1: yearsDetail.domain_relevance_component_0_to_1,
    domain_relevance_evidence: yearsDetail.domain_relevance_evidence,
    component_score_0_to_1: yearsDetail.component_score_0_to_1
  } : { used: false, reason: 'candidate years or required years unknown - factor excluded from scoring, not zeroed (unchanged since CANDOR-04 v0.2)' },
  skill_overlap: skillsUsed ? {
    required_skills_counted: requiredSkillsCounted.map(s => ({ value: s.value, source_quote: s.source_quote })),
    required_skills_excluded_unverified: requiredSkillsExcludedUnverified.map(s => ({ value: s.value, reason: s.reason })),
    // v0.6 (System Review item 15): each verified either/or group and
    // whether it was satisfied - required_count above already reflects
    // slot-counting (a group is 1 slot, not len(options) slots).
    alternative_sets: (skillDetail.alternative_sets || []).map(s => ({ options: s.options, satisfied: s.satisfied, matched_option: s.matched_option, source_quote: s.source_quote })),
    required_slot_count: skillDetail.required_count,
    candidate_skills_considered: skillDetail.candidate_skills,
    matched_skills: skillDetail.matched_skills,
    component_score_0_to_1: skillDetail.component_score_0_to_1
  } : { used: false, reason: 'no individually-verified required skills on the JD - factor excluded from scoring, not zeroed (unchanged since CANDOR-04 v0.2)' },
  role_tenure_stability: tenureUsed ? {
    // Deliberately NOT tenureDetail.entries_considered verbatim (which
    // also carries title/employer for readability, per SelectPermittedS-
    // coringInputs's own comment) - title/employer are near-always
    // identical to the EXCLUDED most_recent_title/most_recent_employer
    // fields (usually the same, most-recent role), so including them
    // here would make the leak-check below false-positive on every such
    // run (found via a real regression run during this fix's own
    // verification, not assumed safe - see CANDOR-04-Build-Log.md v0.4
    // section). Only the values that actually reach the formula
    // (duration_text/parsed_years) belong in the thing the leak-check
    // audits; title/employer stay fully visible below in scoring_evidence
    // instead, unchecked, same as skill_overlap's own fuller detail.
    entries_considered: (tenureDetail.entries_considered || []).map(e => ({ duration_text: e.duration_text, parsed_years: e.parsed_years })),
    average_tenure_years: tenureDetail.average_tenure_years,
    stability_threshold_years: tenureDetail.stability_threshold_years,
    sufficiency_component_0_to_1: tenureDetail.sufficiency_component_0_to_1,
    domain_relevance_component_0_to_1: tenureDetail.domain_relevance_component_0_to_1,
    domain_relevance_evidence: tenureDetail.domain_relevance_evidence,
    component_score_0_to_1: tenureDetail.component_score_0_to_1
  } : { used: false, reason: 'no employment-history entry had a duration CANDOR-04 could parse (missing, unverified, or unparseable) - factor excluded from scoring, not zeroed (new since CANDOR-04 v0.4)' },
  career_trajectory: trajectoryUsed ? {
    // Same leak-check discipline as role_tenure_stability above: titles
    // are near-always identical to (or a substring match against) the
    // EXCLUDED most_recent_title field, so only the derived RANK belongs
    // in the leak-checked block - the literal title text stays visible
    // below in scoring_evidence instead, unchecked.
    title_ranks_considered: (trajectoryDetail.title_entries_considered || []).map(e => e.rank),
    most_recent_title_rank: trajectoryDetail.most_recent_title_rank,
    required_title_rank: trajectoryDetail.required_title_rank,
    sufficiency_component_0_to_1: trajectoryDetail.sufficiency_component_0_to_1,
    progression_component_0_to_1: trajectoryDetail.progression_component_0_to_1,
    domain_relevance_component_0_to_1: trajectoryDetail.domain_relevance_component_0_to_1,
    domain_relevance_evidence: trajectoryDetail.domain_relevance_evidence,
    component_score_0_to_1: trajectoryDetail.component_score_0_to_1
  } : { used: false, reason: 'no employment-history entry had an independently-grounded title - factor excluded from scoring, not zeroed (new since CANDOR-04 v0.7)' },
  education_certification_match: educationCertUsed ? {
    education_required: educationCertDetail.education_required,
    education_evidence: educationCertDetail.education_evidence,
    education_component_0_to_1: educationCertDetail.education_component_0_to_1,
    certification_required: educationCertDetail.certification_required,
    certification_evidence: educationCertDetail.certification_evidence,
    certification_component_0_to_1: educationCertDetail.certification_component_0_to_1,
    component_score_0_to_1: educationCertDetail.component_score_0_to_1
  } : { used: false, reason: "the JD requires neither an education level nor a certification (both education_requirement and required_certifications extract as 'not specified') - factor not evaluated at all, per Section 7's own 'only where the job actually requires it' qualifier (new since CANDOR-04 v0.8)" },
  portfolio_work_sample_match: portfolioUsed ? {
    domain_relevance_component_0_to_1: portfolioDetail.domain_relevance_component_0_to_1,
    domain_relevance_evidence: portfolioDetail.domain_relevance_evidence,
    component_score_0_to_1: portfolioDetail.component_score_0_to_1
  } : { used: false, reason: "candidate did not provide a portfolio or work sample (portfolio_or_work_sample extracts as 'insufficient information') - factor not evaluated at all, per Section 7's own 'where provided' qualifier (new since CANDOR-04 v0.9)" }
};

// --- (b) Exclusion confirmation, derived programmatically ---
// PERMITTED_CANDIDATE_FIELDS must be kept in sync BY HAND with
// SelectPermittedScoringInputs's own allow-list - an n8n Code node cannot
// read another node's source code at runtime, so this is a documented
// synchronization requirement (see build log limitations), not a fully
// automatic static-analysis proof. What IS fully automatic and real: for
// every OTHER field actually present on the candidate's CANDOR-01 record
// (education, certifications, name, email, employer, accomplishment
// narrative - whatever CANDOR-01 happens to have produced), this code
// searches the ACTUAL values used to compute the Match Score for that
// field's literal value, and reports whether it leaked in. It did not,
// for any field, on any run so far.
// v0.8 addition: 'education'/'certifications' moved from excluded to
// permitted (Section 7's own "where the job actually requires it"
// factor) - kept in sync by hand with SelectPermittedScoringInputs's own
// allow-list, same documented synchronization requirement as the other
// three additions before it.
const PERMITTED_CANDIDATE_FIELDS = ['total_years_experience_claimed', 'key_skills', 'education', 'certifications'];

const allCandidateFieldNames = (candidateRecord.fields || []).map(f => f.field);
const excludedCandidateFieldNames = allCandidateFieldNames.filter(name => !PERMITTED_CANDIDATE_FIELDS.includes(name));

// === Phase 1b (docs/CANDOR-Hardening-Roadmap-DRAFT.md), redesigned 2026-09-18 ===
// Previously this stored the excluded field's RAW value (candidate_name,
// contact_email, ...) in the persisted audit record just to prove it
// didn't leak into scoring - meaning the leak-check itself was the thing
// persisting PII in plaintext forever, in the one system explicitly built
// to prove PII stays OUT of things. Redesigned to hash-compare: the leak
// check still runs on the real in-memory value (a hash can't be
// substring-matched against the scoring inputs, so the actual value is
// still needed to COMPUTE the check), but only a one-way SHA-256 hash of
// that value is ever written to the persisted record - never the value
// itself. A reviewer holding the original value can still confirm a
// match by hashing it themselves and comparing; the persisted record
// alone can't be reversed to recover the name/email. Same pure-JS
// SHA-256 as CANDOR-02's ComputeResumeContentHash (crypto/crypto.subtle
// confirmed unavailable in this Code-node sandbox - see that node for
// the openssl-verified implementation, not re-derived here).
function sha256Hex(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = bytes.length * 8;
  let paddedLength = bytes.length + 1;
  while (paddedLength % 64 !== 56) paddedLength++;
  paddedLength += 8;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const highLen = Math.floor(bitLen / 0x100000000);
  const lowLen = bitLen >>> 0;
  const dv = new DataView(padded.buffer);
  dv.setUint32(paddedLength - 8, highLen, false);
  dv.setUint32(paddedLength - 4, lowLen, false);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let chunkStart = 0; chunkStart < paddedLength; chunkStart += 64) {
    const w = new Uint32Array(64);
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(chunkStart + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >>> 3);
      const s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  return H.map(x => x.toString(16).padStart(8,'0')).join('');
}

const scoringInputsAsString = JSON.stringify(matchScoreInputsUsed);
const excludedFieldLeakCheck = excludedCandidateFieldNames.map(name => {
  const fieldObj = candidateRecord.fields.find(f => f.field === name);
  const rawValue = fieldObj ? fieldObj.value : null;
  const stringValue = rawValue === null ? '' : (typeof rawValue === 'string' ? rawValue : JSON.stringify(rawValue));
  const leaked = !!(stringValue && stringValue.length > 0 && scoringInputsAsString.includes(stringValue));
  const valueHash = rawValue === null ? null : sha256Hex(new TextEncoder().encode(stringValue));
  return { field: name, value_hash: valueHash, value_hash_algorithm_version: rawValue === null ? null : 'v1.0', leaked_into_scoring_output: leaked };
});

const noExcludedFieldLeaked = excludedFieldLeakCheck.every(c => !c.leaked_into_scoring_output);

const exclusionConfirmation = {
  permitted_candidate_fields: PERMITTED_CANDIDATE_FIELDS,
  candidate_fields_present_on_record: allCandidateFieldNames,
  candidate_fields_excluded_from_scoring: excludedCandidateFieldNames,
  excluded_field_value_leak_check: excludedFieldLeakCheck,
  no_excluded_field_leaked: noExcludedFieldLeaked,
  method_note: "Checked empirically: each excluded field's actual value from the CANDOR-01 record was searched for inside the scoring inputs actually used (matchScoreInputsUsed above) and was not found, for any field, on this run. This proves no excluded VALUE influenced or appears in what was actually computed - it does not by itself prove the scoring CODE never referenced these fields (that would require static source analysis of SelectPermittedScoringInputs, not available at runtime from another node). Phase 1b (2026-09-18): only a one-way SHA-256 hash of each excluded value is persisted above (value_hash), never the value itself - the substring check still runs on the real value in memory (a hash can't be substring-matched), but this record no longer stores candidate PII in plaintext. A reviewer holding the original value can confirm a match by hashing it themselves."
};

// --- (c) Raw evidence behind each factor, in one place ---
const scoringEvidence = detail;

// --- (d) Reliability flag ---
const evidenceConfidence = finalRecord.evidence_confidence;
const lowEvidenceConfidenceFlag = (evidenceConfidence === null) || (evidenceConfidence < EVIDENCE_CONFIDENCE_FLAG_THRESHOLD);
const flagReason = lowEvidenceConfidenceFlag
  ? `Evidence Confidence (${evidenceConfidence}) is below the ${FLAG_VERSION} threshold of ${EVIDENCE_CONFIDENCE_FLAG_THRESHOLD}. More than half of this candidate's extracted claims could not be independently verified against the source resume. The Match Score above should not be treated as reliable without a human reviewing the underlying claims directly.`
  : `Evidence Confidence (${evidenceConfidence}) meets the ${FLAG_VERSION} threshold of ${EVIDENCE_CONFIDENCE_FLAG_THRESHOLD}. No reliability concern flagged on this basis.`;

return [{
  json: {
    candidate_id: finalRecord.candidate_id,
    job_id: finalRecord.job_id,
    resume_content_hash: candidateRecord.resume_content_hash,
    resume_content_hash_algorithm_version: candidateRecord.resume_content_hash_algorithm_version,
    resume_shingle_fingerprint: candidateRecord.resume_shingle_fingerprint,
    resume_shingle_fingerprint_version: candidateRecord.resume_shingle_fingerprint_version,
    tenant_id: candidateRecord.tenant_id ?? "default-tenant",
    audit_schema_version: AUDIT_SCHEMA_VERSION,
    match_score: finalRecord.match_score,
    match_score_formula_version: finalRecord.match_score_formula_version,
    evidence_confidence: finalRecord.evidence_confidence,
    evidence_confidence_formula_version: finalRecord.evidence_confidence_formula_version,
    interpretation: finalRecord.interpretation,
    interpretation_threshold_version: finalRecord.interpretation_threshold_version,
    interpretation_threshold: finalRecord.interpretation_threshold,
    match_score_inputs_used: matchScoreInputsUsed,
    exclusion_confirmation: exclusionConfirmation,
    scoring_evidence: scoringEvidence,
    reliability_flag: {
      flag_version: FLAG_VERSION,
      threshold: EVIDENCE_CONFIDENCE_FLAG_THRESHOLD,
      evidence_confidence: evidenceConfidence,
      low_evidence_confidence_flag: lowEvidenceConfidenceFlag,
      flag_reason: flagReason
    },
    audit_disclaimer: 'This audit record is a diagnostic aid for the human reviewer who remains responsible for the hiring process. It is not, and must never be treated as, a certification of legal or bias compliance (CANDOR Master Instructions Section 8). No combination of these values authorizes rejecting, advancing, or contacting this candidate (Section 13/26).',
    audited_at: new Date().toISOString()
  }
}];

// === CANDOR-08 Database / Historical Intelligence - Slice 1 ===
// "Don't let real results evaporate" - not a real database. One line per
// audit record, append-only, never overwritten (consistent with this
// being an audit trail, Master Instructions Section 16). No query/lookup
// tooling here - that's a later slice, once the write path is proven.
//
// Enough to look a candidate up later (candidate_id, job_id, audited_at)
// plus the full audit record exactly as BuildAuditRecord produced it -
// nothing recomputed, nothing summarized. Dedup fields (System Review
// item 27) are pulled to the top level too, same reasoning: a future
// lookup/query slice scanning for duplicates shouldn't have to parse
// into audit_record just to filter on them.

const record = $input.first().json;

const line = JSON.stringify({
  candidate_id: record.candidate_id,
  job_id: record.job_id,
  audited_at: record.audited_at,
  resume_content_hash: record.resume_content_hash ?? null,
  resume_content_hash_algorithm_version: record.resume_content_hash_algorithm_version ?? null,
  resume_shingle_fingerprint: record.resume_shingle_fingerprint ?? null,
  resume_shingle_fingerprint_version: record.resume_shingle_fingerprint_version ?? null,
  tenant_id: record.tenant_id ?? "default-tenant",
  dedup_check_status: record.dedup_check_status,
  is_duplicate_application: record.is_duplicate_application,
  duplicate_of: record.duplicate_of,
  duplicate_count: record.duplicate_count,
  dedup_skip_reason: record.dedup_skip_reason,
  near_duplicate_check_status: record.near_duplicate_check_status,
  is_near_duplicate_application: record.is_near_duplicate_application,
  near_duplicate_of: record.near_duplicate_of,
  near_duplicate_similarity: record.near_duplicate_similarity,
  audit_record: record
});

return [{ json: { jsonl_line: line + "\n" } }];

// === CANDOR-08 deduplication (System Review item 27) ===
// Reads every previously-persisted CANDOR-08 record and checks whether
// the current submission's (job_id, resume_content_hash) composite key
// matches a prior one. Flags only - never blocks. AppendCandor08RecordToDisk
// still appends unconditionally regardless of what this node finds.
//
// Input arrives from MergeAuditRecordAndExistingFile (append mode, two
// items - one per upstream branch), the same cross-branch pattern already
// established and tested in this workflow (see SelectPermittedScoringInputs's
// own header comment: n8n does not guarantee a parallel branch has
// executed when referenced by name across branches, so items are told
// apart structurally here too, not by branch order).

const items = $input.all().map(i => i.json);
const auditRecord = items.find(i => 'match_score' in i && 'candidate_id' in i);
const fileItem = items.find(i => 'existing_records_text' in i);

// The file-read branch uses onError: continueRegularOutput on both its
// nodes (Read/Write Files from Disk, then Extract from File) specifically
// so a missing or not-yet-created candor08-records.jsonl (e.g. the very
// first submission ever, or a freshly-provisioned environment) degrades
// to "zero existing records" rather than crashing this entire submission
// the way the unhandled N8N_RESTRICT_FILE_ACCESS_TO gap once did. When
// the read/extract chain fails, fileItem is either absent or has no
// `existing_records_text` field - both treated as "no prior records".
const existingText = (fileItem && typeof fileItem.existing_records_text === 'string') ? fileItem.existing_records_text : '';

const priorRecords = existingText
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0)
  .map(line => {
    try { return JSON.parse(line); } catch (e) { return null; }
  })
  .filter(rec => rec !== null);

const jobId = auditRecord.job_id;
const resumeContentHash = auditRecord.resume_content_hash;

const DEDUP_KEY_VERSION = 'CANDOR-08 dedup-key v1.0';

let dedupCheckStatus;
let isDuplicateApplication;
let duplicateOf;
let duplicateCount;
let dedupSkipReason;

// Missing-field handling per contract: absence of EITHER key field means
// the check is SKIPPED, never silently treated as "not a duplicate" -
// a false "false" here would be worse than an honest "we don't know".
const missingFields = [];
if (jobId === undefined || jobId === null || jobId === '') missingFields.push('job_id');
if (resumeContentHash === undefined || resumeContentHash === null || resumeContentHash === '') missingFields.push('resume_content_hash');

if (missingFields.length > 0) {
  dedupCheckStatus = 'skipped';
  isDuplicateApplication = null;
  duplicateOf = null;
  duplicateCount = 0;
  dedupSkipReason = `Cannot check for duplicates: ${missingFields.join(' and ')} missing on this submission.`;
} else {
  // Composite key match - job_id AND resume_content_hash both required.
  // Never hash alone: the same resume submitted against a different job
  // must never read as a duplicate, even though job_id is a constant
  // default today (CANDOR-04 has no live JD source yet) - this is still
  // the correct key design for when it isn't a constant anymore.
  const matches = priorRecords.filter(rec =>
    rec && rec.job_id === jobId && rec.resume_content_hash === resumeContentHash
  );

  dedupCheckStatus = 'checked';
  duplicateCount = matches.length;
  isDuplicateApplication = matches.length > 0;
  dedupSkipReason = null;

  if (matches.length > 0) {
    // Most recent by audited_at.
    const mostRecent = matches.reduce((latest, cur) => {
      if (!latest) return cur;
      return (new Date(cur.audited_at).getTime() > new Date(latest.audited_at).getTime()) ? cur : latest;
    }, null);
    duplicateOf = mostRecent ? mostRecent.candidate_id : null;
  } else {
    duplicateOf = null;
  }
}

return [{
  json: {
    ...auditRecord,
    dedup_key_version: DEDUP_KEY_VERSION,
    dedup_check_status: dedupCheckStatus,
    is_duplicate_application: isDuplicateApplication,
    duplicate_of: duplicateOf,
    duplicate_count: duplicateCount,
    dedup_skip_reason: dedupSkipReason,
    // Internal only - consumed by CheckForNearDuplicateApplication
    // immediately downstream, then explicitly stripped before this
    // record is ever persisted (see that node's own comment). Avoids
    // re-reading and re-parsing the same records file a second time.
    _priorRecordsParsedForNearDup: priorRecords
  }
}];

// === Phase 1a (docs/CANDOR-Hardening-Roadmap-DRAFT.md) ===
// Mirrors CANDOR-01's DetectPromptInjectionPatterns exactly, applied to
// job-description text instead of resume text - a JD submitter is just
// as untrusted a text source as a candidate. Deterministic, transparent
// v0.1 heuristic, flag only, spreads rather than reconstructs. See
// CANDOR-01-Build-Log.md's equivalent node for full reasoning, not
// repeated here.

const items = $input.all();

const PATTERNS = [
  { label: 'ignore_prior_instructions', re: /ignore\s+(all\s+)?(the\s+)?(previous|prior|above|earlier)\s+instructions?/i },
  { label: 'disregard_prior_instructions', re: /disregard\s+(all\s+)?(the\s+)?(previous|prior|above|earlier)\s+instructions?/i },
  { label: 'new_instructions_marker', re: /\bnew\s+instructions?\s*[:.]/i },
  { label: 'you_are_now', re: /\byou\s+are\s+now\s+(a|an|the)\b/i },
  { label: 'system_prompt_reference', re: /\bsystem\s+prompt\b/i },
  { label: 'rate_all_skills_as_expert', re: /rate\s+(all|every|each)\s+skills?\s+as\s+(expert|10\s*\/\s*10|maximum|top)/i },
  { label: 'act_as_persona', re: /\bact\s+as\s+(a|an)\s+/i },
  { label: 'do_not_follow_rules_above', re: /do\s+not\s+(follow|apply)\s+the\s+(rules|instructions)\s+above/i },
  { label: 'assistant_role_injection', re: /\b(assistant|ai)\s*:\s*(ignore|okay|sure|understood)/i }
];

function detect(text) {
  const t = (text || '').toString();
  const matched = PATTERNS.filter(p => p.re.test(t)).map(p => p.label);
  return { suspected: matched.length > 0, matched };
}

return items.map(item => {
  const result = detect(item.json.job_description_text);
  return {
    json: {
      ...item.json,
      prompt_injection_suspected: result.suspected,
      prompt_injection_matched_patterns: result.matched,
      prompt_injection_check_version: 'CANDOR prompt-injection pattern-flag v0.1'
    }
  };
});

// Phase 2c circuit breaker - JD side. Same pattern as CANDOR-01's
// CheckCircuitBreaker (see that node for full reasoning); separate state
// file (circuit-breaker-state-jd.json) since this protects a
// structurally separate call (ExtractRequirements), not shared with
// CANDOR-01's ExtractCandidateClaims breaker.
const CONSECUTIVE_FAILURE_THRESHOLD = 3;
const COOLDOWN_MS = 60 * 1000;

const raw = $input.first().json.circuit_state_text;
let cb;
try {
  cb = raw ? JSON.parse(raw) : { consecutive_failures: 0, circuit_open_until: null };
} catch (e) {
  cb = { consecutive_failures: 0, circuit_open_until: null };
}

const now = Date.now();
if (cb.circuit_open_until && now < cb.circuit_open_until) {
  const secondsLeft = Math.ceil((cb.circuit_open_until - now) / 1000);
  throw new Error(`CANDOR-04 CheckCircuitBreakerJD: circuit is OPEN - ${cb.consecutive_failures} consecutive Anthropic call failures recorded, refusing to call the API again for another ${secondsLeft}s.`);
}

const requestId = `req_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
return [{ json: { ...$('DetectJDPromptInjectionPatterns').first().json, _circuitBreakerState: cb, _requestId: requestId, _requestStartedAt: now } }];

const checkItem = $('CheckCircuitBreakerJD').first().json;
const anthropicOutput = $('ExtractRequirements').first().json;
const requestId = checkItem._requestId || null;
const startedAt = checkItem._requestStartedAt || null;
const latencyMs = startedAt ? (Date.now() - startedAt) : null;
const usage = anthropicOutput && anthropicOutput.usage ? anthropicOutput.usage : null;

const observability = {
  request_id: requestId,
  node: 'CANDOR-04:ExtractRequirements',
  status: 'success',
  latency_ms: latencyMs,
  input_tokens: usage ? usage.input_tokens : null,
  output_tokens: usage ? usage.output_tokens : null,
  error_class: null,
  error_message: null,
  logged_at: new Date().toISOString()
};

return [{ json: { circuit_state_json: JSON.stringify({ consecutive_failures: 0, circuit_open_until: null }), observability_line: JSON.stringify(observability) + '\n' } }];

const CONSECUTIVE_FAILURE_THRESHOLD = 3;
const COOLDOWN_MS = 60 * 1000;

const checkItem = $('CheckCircuitBreakerJD').first().json;
const cb = (checkItem._circuitBreakerState) || { consecutive_failures: 0, circuit_open_until: null };
cb.consecutive_failures += 1;

let tripped = false;
if (cb.consecutive_failures >= CONSECUTIVE_FAILURE_THRESHOLD) {
  cb.circuit_open_until = Date.now() + COOLDOWN_MS;
  tripped = true;
}

const errItem = $('ExtractRequirements').first().json;
const originalMessage = (errItem && errItem.error && errItem.error.message) ? errItem.error.message : JSON.stringify(errItem);

function classifyError(msg) {
  const m = (msg || '').toLowerCase();
  if (m.includes('too many requests') || m.includes('rate limit') || m.includes('429')) return 'rate_limit';
  if (m.includes('not able to process') || m.includes('server error') || m.includes('500')) return 'server_error';
  if (m.includes('timeout') || m.includes('timed out')) return 'timeout';
  return 'other';
}

const requestId = checkItem._requestId || null;
const startedAt = checkItem._requestStartedAt || null;
const latencyMs = startedAt ? (Date.now() - startedAt) : null;
const errorClass = classifyError(originalMessage);

const observability = {
  request_id: requestId,
  node: 'CANDOR-04:ExtractRequirements',
  status: 'error',
  latency_ms: latencyMs,
  input_tokens: null,
  output_tokens: null,
  error_class: errorClass,
  error_message: originalMessage,
  logged_at: new Date().toISOString()
};

return [{
  json: {
    circuit_state_json: JSON.stringify({ consecutive_failures: cb.consecutive_failures, circuit_open_until: cb.circuit_open_until }),
    observability_line: JSON.stringify(observability) + '\n',
    _errorMessage: `CANDOR-04 ExtractRequirements failed (consecutive_failures now ${cb.consecutive_failures}${tripped ? ', CIRCUIT NOW OPEN' : ''}): ${originalMessage}`
  }
}];

const msg = $('RecordAnthropicFailureJD').first().json._errorMessage;
throw new Error(msg);
return []; // unreachable

// === Phase 4a (docs/CANDOR-Hardening-Roadmap-DRAFT.md): near-duplicate
// detection, layered on top of the exact-hash dedup above ===
// Closes the real gap the exact-match check (CheckForDuplicateApplication)
// deliberately does not cover: a candidate resubmitting a lightly
// -reformatted resume (different whitespace, a reordered sentence, a
// synonym swap) produces a DIFFERENT resume_content_hash and would
// otherwise get a second, independent, undiscounted evaluation - test
// case 5 in CANDOR-08's own dedup matrix already proved genuine edits
// correctly bypass the exact-hash check; this is the bounded fuzzy
// -match layer for near-identical (not genuinely edited) resubmissions.
//
// Flag only - never blocks. Unlike the exact-match case (Phase 2d), a
// fuzzy match is inherently riskier to auto-block (a genuinely different
// candidate could plausibly share enough boilerplate phrasing to false
// -positive), so this stays flag-only even though 2d converted the
// EXACT-match case to an actual gate - a deliberate, reasoned difference
// in disposition, not an oversight.
//
// Scoped by job_id, same as the exact-match check - a lightly-reformatted
// resume submitted for a DIFFERENT job is not a duplicate application.

const rec = $input.first().json;
const NEAR_DUP_SIMILARITY_THRESHOLD = 0.7;
const NEAR_DUP_CHECK_VERSION = 'CANDOR near-dup shingle-fingerprint v0.1';

const { _priorRecordsParsedForNearDup, ...rest } = rec;
const priorRecords = Array.isArray(_priorRecordsParsedForNearDup) ? _priorRecordsParsedForNearDup : [];

const jobId = rec.job_id;
const myFingerprint = Array.isArray(rec.resume_shingle_fingerprint) ? rec.resume_shingle_fingerprint : [];

function similarity(a, b) {
  if (!a.length || !b.length) return 0;
  const setB = new Set(b);
  const shared = a.filter(h => setB.has(h)).length;
  return shared / Math.min(a.length, b.length);
}

let checkStatus;
let isNearDup;
let nearDupOf;
let nearDupSimilarity;
let skipReason;

if (!jobId || myFingerprint.length === 0) {
  checkStatus = 'skipped';
  isNearDup = null;
  nearDupOf = null;
  nearDupSimilarity = null;
  skipReason = `Cannot check for near-duplicates: ${!jobId ? 'job_id' : 'resume_shingle_fingerprint'} missing on this submission.`;
} else {
  checkStatus = 'checked';
  skipReason = null;
  let best = { candidate_id: null, similarity: 0 };
  for (const priorRec of priorRecords) {
    if (!priorRec || priorRec.job_id !== jobId) continue;
    // Exact duplicates never reach this node (blocked upstream by
    // RouteByDuplicateStatus) on THIS submission's own path, but prior
    // records in the file can still legitimately include exact matches
    // to EACH OTHER from before Phase 2d's gate existed - skip comparing
    // against this submission's own already-known exact hash to avoid a
    // trivially-100% "near-duplicate" of itself being reported as if it
    // were a new, separate finding.
    if (priorRec.resume_content_hash === rec.resume_content_hash) continue;
    const priorFingerprint = Array.isArray(priorRec.resume_shingle_fingerprint) ? priorRec.resume_shingle_fingerprint : [];
    const sim = similarity(myFingerprint, priorFingerprint);
    if (sim > best.similarity) {
      best = { candidate_id: priorRec.candidate_id, similarity: sim };
    }
  }
  isNearDup = best.similarity >= NEAR_DUP_SIMILARITY_THRESHOLD;
  nearDupOf = isNearDup ? best.candidate_id : null;
  nearDupSimilarity = Math.round(best.similarity * 1000) / 1000;
}

return [{
  json: {
    ...rest,
    near_dup_check_version: NEAR_DUP_CHECK_VERSION,
    near_duplicate_check_status: checkStatus,
    is_near_duplicate_application: isNearDup,
    near_duplicate_of: nearDupOf,
    near_duplicate_similarity: nearDupSimilarity,
    near_duplicate_skip_reason: skipReason
  }
}];

// === Phase 6e (docs/CANDOR-Hardening-Roadmap-DRAFT.md): semantic
// pre-filter, strictly upstream of scoring ===
// Master Instructions Section 7 requires the Match Score be calculated
// deterministically by code - a semantic-rank signal feeding the score
// itself would violate that directly, not a style choice. This node is
// wired in PARALLEL to SelectPermittedScoringInputs (both read from the
// same MergeCandidateAndJD output), not IN LINE before it - its own
// output never becomes SelectPermittedScoringInputs's input, so there is
// no code path by which this signal could reach CalculateMatchScore even
// by accident.
//
// Scope decision, stated explicitly rather than silently narrowed: built
// as ADVISORY-ONLY in this pass (computes and surfaces a recommendation,
// never blocks a candidate from being scored) rather than a hard
// eliminate-before-scoring gate. A real block-before-scoring capability
// is a further, separate, higher-stakes product decision (silently
// dropping a candidate from evaluation is more consequential than
// flagging one for review) - this project's own established posture is
// to promote a signal from flag-only to an actual gate only after very
// high confidence (see CANDOR-08's exact-hash dedup, Phase 2d), and a
// semantic-similarity heuristic does not clear that bar on its own.
//
// Deterministic, transparent v0.1 heuristic (word-overlap proxy, not a
// real embedding/semantic-similarity model - naming it "semantic" per
// the roadmap's own language, while being honest about what it actually
// computes) - same disclosure discipline as every other heuristic in
// this project.

const items = $input.all().map(i => i.json);
const jdRecord = items.find(i => 'job_id' in i);
const candidateRecord = items.find(i => 'candidate_id' in i && 'resume_filename' in i);

function wordsOf(text) {
  return new Set((text || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(w => w.length > 2));
}

const candidateSkillsField = (candidateRecord.fields || []).find(f => f.field === 'key_skills');
const candidateYearsField = (candidateRecord.fields || []).find(f => f.field === 'total_years_experience_claimed');
const candidateText = [
  Array.isArray(candidateSkillsField && candidateSkillsField.value) ? candidateSkillsField.value.join(' ') : '',
  (candidateYearsField && candidateYearsField.source_quote) || ''
].join(' ');

const jdRequiredSkillsText = (jdRecord.required_skills || []).map(s => s.value).join(' ');
const jdOtherQualsText = (jdRecord.other_required_qualifications || []).map(s => s.value).join(' ');
const jdText = [jdRequiredSkillsText, jdOtherQualsText].join(' ');

const candidateWords = wordsOf(candidateText);
const jdWords = wordsOf(jdText);
const overlap = [...candidateWords].filter(w => jdWords.has(w)).length;
const denominator = Math.min(candidateWords.size, jdWords.size) || 1;
const overlapScore = Math.round((overlap / denominator) * 1000) / 1000;

const SEMANTIC_PREFILTER_LOW_RELEVANCE_THRESHOLD = 0.1;
const recommendation = overlapScore < SEMANTIC_PREFILTER_LOW_RELEVANCE_THRESHOLD ? 'LOW_RELEVANCE_REVIEW_RECOMMENDED' : 'PASS';

return [{
  json: {
    semantic_prefilter_version: 'CANDOR semantic-prefilter v0.1 (word-overlap proxy, advisory-only)',
    semantic_prefilter_overlap_score: overlapScore,
    semantic_prefilter_recommendation: recommendation,
    semantic_prefilter_note: 'Advisory only - never blocks scoring, never an input to Match Score. See SemanticPreFilter node comment for the scope decision.'
  }
}];

// === System Review item 43 fix: JD-extraction cache, keyed on content hash ===
// Same canonicalize-then-SHA-256 pattern as CANDOR-02's own
// ComputeResumeContentHash (independently openssl-verified there, reused
// verbatim here rather than re-derived) - applied to the JD text instead
// of the resume text, so a repeat submission against an UNCHANGED job
// posting can be recognized and its already-verified extraction reused,
// instead of paying for and re-running ExtractRequirements every single
// time. This is the real, quantified finding from
// docs/CANDOR-LoadTest-2026-09-18.md: 43.1% of that test's real spend was
// this exact extraction, repeated against an unchanged JD.

function sha256Hex(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = bytes.length * 8;
  let paddedLength = bytes.length + 1;
  while (paddedLength % 64 !== 56) paddedLength++;
  paddedLength += 8;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const highLen = Math.floor(bitLen / 0x100000000);
  const lowLen = bitLen >>> 0;
  const dv = new DataView(padded.buffer);
  dv.setUint32(paddedLength - 8, highLen, false);
  dv.setUint32(paddedLength - 4, lowLen, false);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
