  }
  return H.map(x => x.toString(16).padStart(8,'0')).join('');
}

const item = $input.first().json;
const rawText = typeof item.job_description_text === 'string' ? item.job_description_text : '';

const canonical = rawText
  .normalize('NFC')
  .replace(/\r\n?/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const hashHex = sha256Hex(new TextEncoder().encode(canonical));

return [{
  json: {
    ...item,
    jd_content_hash: hashHex,
    jd_content_hash_algorithm_version: 'v1.0'
  }
}];

// Reach back by node name for the real JD fields - this node's own
// $input carries only the cache file's raw text (or nothing, on a
// missing file), same "reach back after a file op" pattern already
// established in this workflow (CheckCircuitBreakerJD, ParseRequirementsJSON).
const jdItem = $('ComputeJDContentHash').first().json;
const fileItem = $input.first().json;

// Same missing-file tolerance as CANDOR-08's own CheckForDuplicateApplication:
// ReadJDExtractionCacheFile/ExtractJDExtractionCacheFileText both set
// onError: continueRegularOutput, so a missing or not-yet-created cache
// file (the very first JD extraction ever) degrades to "no cache
// entries" rather than crashing this submission.
const existingText = (fileItem && typeof fileItem.existing_jd_cache_text === 'string') ? fileItem.existing_jd_cache_text : '';

const cacheLines = existingText
  .split('\n')
  .map(line => line.trim())
  .filter(line => line.length > 0)
  .map(line => { try { return JSON.parse(line); } catch (e) { return null; } })
  .filter(rec => rec !== null);

const match = cacheLines.find(rec => rec && rec.jd_content_hash === jdItem.jd_content_hash);

return [{
  json: {
    ...jdItem,
    jd_cache_version: 'CANDOR-04 JD-extraction-cache v1.0',
    jd_cache_hit: !!match,
    cached_verified_record: match ? match.verified_record : null,
    cached_at: match ? match.cached_at : null
  }
}];

// Cache hit: reuse the exact, already-verified extraction produced by a
// prior submission against this SAME job_description_text (matched
// byte-for-byte via jd_content_hash) - no Anthropic call made. Output is
// shaped IDENTICALLY to VerifyRequirementsAgainstSource's own return
// value, because it literally IS that node's earlier output, persisted
// then retrieved unchanged - so a match_score computed from a cache hit
// is byte-identical to what a fresh real extraction of this same JD text
// would have produced.
const item = $input.first().json;
return [{ json: item.cached_verified_record }];

// Only a successful (PARSED_OK) verified extraction is worth caching - a
// PARSE_FAILED record is never persisted, so a future submission against
// the same JD text gets a fresh real attempt instead of a cached failure
// repeating forever.
const verifiedRecord = $input.first().json;
const jdItem = $('ComputeJDContentHash').first().json;

const shouldCache = verifiedRecord.extraction_status === 'PARSED_OK';

if (!shouldCache) {
  return [{ json: { should_write_cache: false } }];
}

const cacheLine = JSON.stringify({
  jd_content_hash: jdItem.jd_content_hash,
  jd_content_hash_algorithm_version: jdItem.jd_content_hash_algorithm_version,
  job_id: verifiedRecord.job_id,
  cached_at: new Date().toISOString(),
  verified_record: verifiedRecord
});

return [{ json: { should_write_cache: true, jsonl_line: cacheLine + '\n' } }];

// Reach back by node name, same established pattern as ParseRequirementsJSON
// after the circuit-breaker file write elsewhere in this workflow - this
// node's own $input carries only the (possibly skipped) file-write
// result, not the verified JD record needed downstream by
// MergeCandidateAndJD/SelectPermittedScoringInputs/SemanticPreFilter.
return [{ json: $('VerifyRequirementsAgainstSource').first().json }];

const anthropicOutput = $('ExtractRequirements').first().json;
const intake = $('IntakeJobDescription').first().json;
const injectionCheck = $('DetectJDPromptInjectionPatterns').first().json;

let rawText = '';
try {
  rawText = anthropicOutput.content[0].text;
} catch (e) {
