}

// Same defensive parsing discipline as CANDOR-01's ParseExtractionJSON:
// the model may wrap output in markdown fences despite being told not
// to - strip that before parsing rather than assuming compliance.
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
}

let extraction = null;
let parseError = null;
try {
  extraction = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

if (!extraction) {
  return [{
    json: {
      job_id: intake.job_id,
      job_title: intake.job_title,
      job_description_text: intake.job_description_text,
      prompt_injection_suspected: injectionCheck.prompt_injection_suspected,
      prompt_injection_matched_patterns: injectionCheck.prompt_injection_matched_patterns,
      extraction_status: 'PARSE_FAILED',
      parse_error: parseError,
      raw_model_output: rawText
    }
